#[derive(Clone, Debug, PartialEq, Eq)]
struct PendingSend {
    id: String,
    text: String,
    /// Uploaded files sent with this message; retries resend the same ids.
    attachments: Vec<model::Attachment>,
    created_at: String,
    sending: bool,
    upload_failed: bool,
    rejection: Option<String>,
    thread_root_id: Option<String>,
    broadcast: bool,
    reply_to: Option<model::MessageReply>,
}

impl PendingSend {
    fn prepare(previous: Option<&Self>, draft: &str, attachments: Vec<model::Attachment>) -> Self {
        previous.map_or_else(
            || Self {
                id: uuid::Uuid::new_v4().to_string(),
                text: draft.into(),
                attachments,
                created_at: Local::now().to_rfc3339(),
                sending: true,
                upload_failed: false,
                rejection: None,
                thread_root_id: None,
                broadcast: false,
                reply_to: None,
            },
            |pending| Self {
                id: pending.id.clone(),
                text: pending.text.clone(),
                attachments: pending.attachments.clone(),
                created_at: pending.created_at.clone(),
                sending: true,
                upload_failed: false,
                rejection: None,
                thread_root_id: pending.thread_root_id.clone(),
                broadcast: pending.broadcast,
                reply_to: pending.reply_to.clone(),
            },
        )
    }

    fn confirmed_by(&self, message: &model::Message, author: &str) -> bool {
        self.id == message.client_message_id
            && message.author.id == author
            && self.thread_root_id == message.thread_root_id
            && self.broadcast == message.broadcast
            && self.reply_to.as_ref().map(|reply| &reply.id)
                == message.reply_to.as_ref().map(|reply| &reply.id)
    }
}

#[derive(Clone)]
struct ThreadView {
    root: String,
    loading: bool,
    has_more: bool,
    before: Option<String>,
    error: Option<String>,
    window: Option<MessageWindow>,
    has_newer: bool,
    /// The last request was an older page: Retry repeats it rather than
    /// reloading the latest replies.
    retry_older: bool,
}

#[derive(Clone, Copy)]
struct MessageWindow {
    start: u64,
    end: Option<u64>,
}

impl MessageWindow {
    fn contains(self, message: &model::Message) -> bool {
        model::sequence(&message.seq)
            .is_ok_and(|seq| seq >= self.start && self.end.is_none_or(|end| seq <= end))
    }
}

/// A block in either direction: a definitive refusal shown in place, never an
/// expired session or lost access that closes the conversation.
fn dm_refusal(code: Option<&str>) -> bool {
    matches!(code, Some("dm_blocked" | "dm_not_accepted"))
}

fn permanent_send_rejection(status: Option<u16>) -> bool {
    matches!(status, Some(400 | 404 | 409 | 413 | 422))
}

/// The composer token that opens suggestions. Their grammars never overlap,
/// so at most one kind is active at a caret.
#[derive(Clone, Debug, PartialEq, Eq)]
enum ComposerToken {
    Emoji(emoji::Token),
    Mention(mentions::Token),
}

impl ComposerToken {
    fn at(text: &str, caret: usize) -> Option<Self> {
        emoji::token(text, caret)
            .map(Self::Emoji)
            .or_else(|| mentions::token(text, caret).map(Self::Mention))
    }

    fn end(&self) -> usize {
        match self {
            Self::Emoji(token) => token.end,
            Self::Mention(token) => token.end,
        }
    }

    fn insert(&self, text: &str, choice: &Suggestion) -> Option<(String, usize)> {
        match (self, choice) {
            (Self::Emoji(token), Suggestion::Emoji(entry)) => {
                emoji::insert(text, token, &entry.emoji)
            }
            (Self::Mention(token), Suggestion::Mention(candidate)) => {
                mentions::insert(text, token, candidate.name())
            }
            _ => None,
        }
    }
}

#[derive(Clone)]
enum Suggestion {
    Emoji(&'static emoji::Entry),
    Mention(mentions::Candidate),
}

/// One composer's suggestion popup, kept by its editor's ID so the channel
/// and thread composers never share a highlight or a dismissal.
#[derive(Default)]
struct SuggestionState {
    token: Option<ComposerToken>,
    selected: usize,
    /// Escape hides the token ending at this caret in this text.
    dismissed: Option<(String, usize)>,
}

impl SuggestionState {
    /// The token at a collapsed caret, unless Escape dismissed it there.
    fn token_at(&self, text: &str, range: egui::text::CCursorRange) -> Option<ComposerToken> {
        if !range.is_empty() {
            return None;
        }
        ComposerToken::at(text, range.primary.index)
            .filter(|token| self.dismissed.as_ref() != Some(&(text.to_owned(), token.end())))
    }
}

/// The people list below a username field (space invite, private channel
/// grant, new DM). The fields share one text and only one shows at a time.
#[derive(Default)]
struct PeopleSuggestions {
    /// The text the highlight and `hidden` belong to.
    text: String,
    selected: usize,
    /// Escape or a selection hides the list until the text changes.
    hidden: bool,
}

impl PeopleSuggestions {
    fn sync(&mut self, text: &str) {
        if self.text != text {
            text.clone_into(&mut self.text);
            self.selected = 0;
            self.hidden = false;
        }
    }

    /// Puts `username` in the field with the caret after it, and hides the list.
    fn choose(
        &mut self,
        context: &egui::Context,
        id: egui::Id,
        value: &mut String,
        username: &str,
    ) {
        username.clone_into(value);
        self.sync(value);
        self.hidden = true;
        let mut state = egui::TextEdit::load_state(context, id).unwrap_or_default();
        state
            .cursor
            .set_char_range(Some(egui::text::CCursorRange::one(
                egui::text::CCursor::new(value.chars().count()),
            )));
        state.store(context, id);
    }
}

/// What a composer's suggestion keys decided before its editor drew.
