/// Satoshi has no tabular figures: lay `text` out with every digit in a cell
/// as wide as the widest digit, so a running timer or a dragged percentage
/// keeps its width (web's `font-variant-numeric: tabular-nums`). Returns the
/// galley and the width to reserve for it.
fn tabular_galley(
    ui: &egui::Ui,
    text: &str,
    font: &egui::FontId,
    color: Color32,
) -> (std::sync::Arc<egui::Galley>, f32) {
    ui.fonts_mut(|fonts| {
        let digit = ('0'..='9')
            .map(|digit| fonts.glyph_width(font, digit))
            .fold(0.0, f32::max);
        let mut job = egui::text::LayoutJob::default();
        let mut width = 0.0;
        // Each character is its own section; a digit's padding is split
        // around it, so the leading space carries the previous one's half.
        let mut carry = 0.0;
        for (start, c) in text.char_indices() {
            let glyph = fonts.glyph_width(font, c);
            let pad = if c.is_ascii_digit() {
                (digit - glyph) / 2.0
            } else {
                0.0
            };
            job.sections.push(egui::text::LayoutSection {
                leading_space: carry + pad,
                byte_range: start..start + c.len_utf8(),
                format: egui::TextFormat::simple(font.clone(), color),
            });
            carry = pad;
            width += glyph + 2.0 * pad;
        }
        job.text = text.into();
        (fonts.layout_job(job), width)
    })
}

/// A label drawn with `tabular_galley`.
fn tabular_label(
    ui: &mut egui::Ui,
    text: &str,
    font: egui::FontId,
    color: Color32,
) -> egui::Response {
    let (galley, width) = tabular_galley(ui, text, &font, color);
    let (rect, response) =
        ui.allocate_exact_size(egui::vec2(width, galley.size().y), egui::Sense::hover());
    ui.painter().galley(rect.min, galley, color);
    response.widget_info(|| egui::WidgetInfo::labeled(egui::WidgetType::Label, true, text));
    response
}

/// Web's 44px history header row ("Load older messages"), shared by threads.
fn history_row<R>(ui: &mut egui::Ui, content: impl FnOnce(&mut egui::Ui) -> R) -> R {
    ui.allocate_ui_with_layout(
        egui::vec2(ui.available_width(), 44.0),
        egui::Layout::left_to_right(egui::Align::Center),
        |ui| {
            ui.set_min_height(44.0);
            ui.spacing_mut().item_spacing.x = 8.0;
            content(ui)
        },
    )
    .inner
}

fn history_button_font() -> egui::FontId {
    egui::FontId::new(11.52, egui::FontFamily::Name("Satoshi Bold".into()))
}

/// Web's quiet bordered history button.
fn history_button(ui: &mut egui::Ui, label: &str, enabled: bool) -> egui::Response {
    ui.spacing_mut().button_padding = egui::vec2(10.0, 6.0);
    toned(
        ui,
        QUIET_TONE,
        enabled,
        egui::Button::new(RichText::new(label).font(history_button_font())),
    )
}

/// A history button centered in its row.
fn centered_history_button(ui: &mut egui::Ui, label: &str, enabled: bool) -> egui::Response {
    let width = ui.fonts_mut(|fonts| {
        fonts
            .layout_no_wrap(label.into(), history_button_font(), MUTED)
            .size()
            .x
    });
    ui.add_space(((ui.available_width() - width - 20.0) / 2.0).max(0.0));
    history_button(ui, label, enabled)
}

/// Web's `SubmitRow`: Cancel, then the primary action, aligned to the end.
/// While `pending`, both are disabled. Returns (cancel, submit).
fn dialog_actions(ui: &mut egui::Ui, label: &str, enabled: bool, pending: bool) -> (bool, bool) {
    let (cancel, submit) = dialog_buttons(
        ui,
        "Cancel",
        label,
        PRIMARY_TONE,
        !pending,
        enabled && !pending,
    );
    (cancel.clicked(), submit.clicked())
}

/// Web's `.space-dialog-actions`: the secondary choice, then the action in
/// `tone`, aligned to the end. The action keeps a minimum width so its
/// pending label ("Leaving…") doesn't shift the row. Returns both responses.
fn dialog_buttons(
    ui: &mut egui::Ui,
    secondary: &str,
    action: &str,
    tone: Tone,
    secondary_enabled: bool,
    action_enabled: bool,
) -> (egui::Response, egui::Response) {
    ui.add_space(20.0);
    ui.horizontal(|ui| {
        ui.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {
            ui.spacing_mut().button_padding.x = 12.0;
            let action = toned(
                ui,
                tone,
                action_enabled,
                egui::Button::new(bold(action).size(12.0)).min_size(egui::vec2(112.0, 36.0)),
            );
            let secondary = secondary_button(ui, secondary, secondary_enabled);
            (secondary, action)
        })
        .inner
    })
    .inner
}

fn message_skeleton(ui: &mut egui::Ui) {
    let (rect, response) = ui.allocate_exact_size(ui.available_size(), egui::Sense::hover());
    response.widget_info(|| {
        egui::WidgetInfo::labeled(egui::WidgetType::Other, ui.is_enabled(), "Loading messages")
    });
    let painter = ui.painter().with_clip_rect(rect.intersect(ui.clip_rect()));
    let width = (rect.width() - 80.0).max(0.0);
    for (row, fraction) in [0.72, 0.92, 0.56, 0.81, 0.64].into_iter().enumerate() {
        let top = rect.top() + 28.0 + row as f32 * 84.0;
        if top + 54.0 > rect.bottom() {
            break;
        }
        painter.circle_filled(egui::pos2(rect.left() + 35.0, top + 17.0), 17.0, BORDER);
        for (offset, length, height) in [
            (0.0, width.min(96.0), 12.0),
            (24.0, width.min(520.0) * fraction, 10.0),
            (42.0, width.min(340.0) * fraction, 10.0),
        ] {
            painter.rect_filled(
                egui::Rect::from_min_size(
                    egui::pos2(rect.left() + 62.0, top + offset),
                    egui::vec2(length, height),
                ),
                4.0,
                BORDER,
            );
        }
    }
}

/// Web's `.chat-state`: a 120 px block at the top of the list, content centered.
fn chat_state(ui: &mut egui::Ui, lines: u8, content: impl FnOnce(&mut egui::Ui)) {
    let height = if lines > 1 { 58.0 } else { 18.0 };
    ui.allocate_ui_with_layout(
        egui::vec2(ui.available_width(), 120.0),
        egui::Layout::top_down(egui::Align::Center),
        |ui| {
            ui.set_min_height(120.0);
            ui.add_space((120.0 - height) / 2.0);
            content(ui);
        },
    );
}

/// Web's composer counter tones.
fn counter_tone(count: usize) -> Color32 {
    match count {
        3_900.. => Color32::from_rgb(0xff, 0x82, 0x7c),
        3_750.. => Color32::from_rgb(0xed, 0xa3, 0x61),
        3_500.. => Color32::from_rgb(0xe4, 0xc7, 0x6a),
        _ => MUTED,
    }
}

/// `toLocaleString()` for the counter: 3500 → "3,500".
fn grouped(count: usize) -> String {
    let digits = count.to_string();
    let mut out = String::new();
    for (index, digit) in digits.chars().enumerate() {
        if index > 0 && (digits.len() - index).is_multiple_of(3) {
            out.push(',');
        }
        out.push(digit);
    }
    out
}

/// Web's three typing dots: 4 px, 3 px apart, bouncing 3 px every 1.2 s.
/// Web's `.chat-typing-dots`. With reduced motion, or while the window is in
/// the background, the dots rest at full strength and nothing repaints.
fn typing_dots(ui: &mut egui::Ui) {
    let (rect, _) = ui.allocate_exact_size(egui::vec2(18.0, 16.0), egui::Sense::hover());
    if !looping(ui) {
        for index in 0..3 {
            let center = egui::pos2(rect.left() + 2.0 + index as f32 * 7.0, rect.center().y);
            ui.painter().circle_filled(center, 2.0, MUTED);
        }
        return;
    }
    let time = ui.input(|input| input.time);
    // As on web, reduced motion keeps the dots still (and idle).
    let still = motion::reduced();
    for index in 0..3 {
        let phase = ((time - index as f64 * 0.15).rem_euclid(1.2) / 1.2) as f32;
        // Keyframes: rest at 0%/60%/100%, peak at 30%, eased in and out.
        let lift = if !still && phase < 0.6 {
            let t = if phase < 0.3 {
                phase / 0.3
            } else {
                (0.6 - phase) / 0.3
            };
            t * t * (3.0 - 2.0 * t)
        } else {
            0.0
        };
        let center = egui::pos2(
            rect.left() + 2.0 + index as f32 * 7.0,
            rect.center().y - 3.0 * lift,
        );
        ui.painter()
            .circle_filled(center, 2.0, MUTED.gamma_multiply(0.45 + 0.55 * lift));
    }
    if !still {
        // A 3px bounce needs no more than 30 frames a second.
        ui.ctx().request_repaint_after(Duration::from_millis(33));
    }
}

/// Web's narrow `.navigation-toggle`: a bordered icon + label button.
fn navigation_toggle(ui: &mut egui::Ui, icon: NavIcon, text: &str) -> egui::Response {
    let galley = ui.painter().layout_no_wrap(
        text.into(),
        egui::FontId::new(11.2, egui::FontFamily::Name("Satoshi Bold".into())),
        MUTED,
    );
    let size = egui::vec2(9.0 + 15.0 + 6.0 + galley.size().x + 9.0, 34.0);
    let (rect, response) = ui.allocate_exact_size(size, egui::Sense::click());
    let hover = response.hovered() || response.has_focus();
    if hover {
        ui.painter().rect_filled(rect, 6.0, SURFACE_HOVER);
    }
    ui.painter().rect_stroke(
        rect,
        6.0,
        Stroke::new(1.0, BORDER),
        egui::StrokeKind::Inside,
    );
    let color = if hover { TEXT } else { MUTED };
    paint_icon(
        ui.painter(),
        egui::Rect::from_center_size(
            egui::pos2(rect.left() + 16.5, rect.center().y),
            egui::vec2(15.0, 15.0),
        ),
        icon,
        color,
    );
    ui.painter().galley_with_override_text_color(
        egui::pos2(rect.left() + 30.0, rect.center().y - galley.size().y / 2.0),
        galley,
        color,
    );
    response
        .widget_info(|| egui::WidgetInfo::labeled(egui::WidgetType::Button, ui.is_enabled(), text));
    response
}

fn destructive(ui: &mut egui::Ui, text: &str) -> egui::Response {
    toned(
        ui,
        DANGER_OUTLINE_TONE,
        true,
        egui::Button::new(text).min_size(egui::vec2(112.0, 36.0)),
    )
}

fn full_bleed_separator(ui: &egui::Ui, y: f32) {
    // Panels clip to their padded content; extend the clip as well as the line.
    let mut painter = ui.painter().clone();
    painter.set_clip_rect(ui.clip_rect().expand2(egui::vec2(12.0, 0.5)));
    painter.hline(
        (ui.max_rect().left() - 12.0)..=(ui.max_rect().right() + 12.0),
        y,
        Stroke::new(1.0, BORDER),
    );
}

fn notices(ui: &mut egui::Ui, error: &Option<String>, warning: &Option<String>) {
    if let Some(error) = error {
        ui.add_space(8.0);
        ui.colored_label(ERROR, error);
    }
    if let Some(warning) = warning {
        ui.add_space(8.0);
        ui.colored_label(Color32::from_rgb(232, 189, 113), warning);
    }
}

/// Part of the Privacy section: opens the account deletion instructions.
fn delete_account_settings(ui: &mut egui::Ui) {
    ui.label(RichText::new("Delete account").size(13.0).color(TEXT));
    ui.add_space(6.0);
    let link = RichText::new("How to delete your account")
        .size(13.0)
        .color(TEXT)
        .underline();
    if ui.link(link).clicked() {
        ui.ctx()
            .open_url(egui::OpenUrl::new_tab(DELETE_ACCOUNT_URL));
    }
}

fn endpoint(args: &[String], fixture: Option<&str>) -> Result<String, String> {
    let explicit = args
        .windows(2)
        .find(|pair| pair[0] == "--api-url")
        .map(|pair| pair[1].clone())
        .or_else(|| std::env::var("CAPER_API_URL").ok());
    let endpoint = explicit.unwrap_or_else(|| {
        if fixture.is_some() {
            "http://127.0.0.1:3001".into()
        } else {
            "https://caper.chat".into()
        }
    });
    if fixture.is_some() {
        let parsed = url::Url::parse(&endpoint)
            .map_err(|_| "Fixture API URL must be a valid loopback URL.".to_owned())?;
        let loopback = parsed
            .host_str()
            .and_then(|host| host.parse::<std::net::IpAddr>().ok())
            .is_some_and(|host| host.is_loopback())
            || parsed.host_str() == Some("localhost");
        if !loopback {
            return Err("--fixture refuses non-loopback API endpoints.".into());
        }
    }
    Ok(endpoint)
}

fn main() -> eframe::Result {
    let args: Vec<String> = std::env::args().collect();
    let fixture = args
        .windows(2)
        .find(|pair| pair[0] == "--fixture")
        .map(|pair| pair[1].clone());
    let endpoint = endpoint(&args, fixture.as_deref()).unwrap_or_else(|message| {
        eprintln!("Caper could not start: {message}");
        std::process::exit(2)
    });
    let api = api::Api::new(&endpoint).unwrap_or_else(|message| {
        eprintln!("Caper could not start: {message}");
        std::process::exit(2)
    });
    let launch_invite = app_link::launch_code(&args);
    if fixture.is_none() {
        // A clicked link while Caper is open goes to that window instead.
        if launch_invite.as_deref().is_some_and(app_link::hand_off) {
            return Ok(());
        }
        if !cfg!(debug_assertions)
            && let Err(error) = app_link::register()
        {
            eprintln!("Caper could not register caper:// links: {error}");
        }
    }
    let viewport_size = if fixture.as_deref().is_some_and(|name| {
        matches!(
            name,
            "parity-narrow"
                | "parity-browse"
                | "parity-opening-narrow"
                | "parity-channel-preview-narrow"
                | "parity-channel-directory-narrow"
                | "parity-voice-rosters-narrow"
                | "parity-voice-crowded-narrow"
                | "parity-voice-list-narrow"
                | "parity-voice-strip-narrow"
                | "parity-voice-join-narrow"
                | "parity-invitation-narrow"
                | "parity-update-narrow"
                | "parity-update-download"
                | "parity-file-drop-narrow"
                | "parity-thread-attachments-narrow"
                | "parity-thread-attachments-ready-narrow"
                | "parity-thread-attachments-rejected-narrow"
                | "parity-whats-new-narrow"
        )
    }) {
        [390.0, 844.0]
    } else {
        [1440.0, 900.0]
    };
    let icon = image::load_from_memory(include_bytes!("../resources/caper-icon.png"))
        .expect("bundled Caper icon is valid PNG")
        .to_rgba8();
    let (width, height) = icon.dimensions();
    let viewport = egui::ViewportBuilder::default()
        .with_inner_size(viewport_size)
        .with_min_inner_size([320.0, 560.0])
        .with_maximized(fixture.is_none())
        .with_icon(egui::IconData {
            rgba: icon.into_raw(),
            width,
            height,
        });
    // Match caper.desktop so Wayland can resolve the packaged icon.
    #[cfg(target_os = "linux")]
    let viewport = viewport.with_app_id("caper");
    eframe::run_native(
        "Caper",
        eframe::NativeOptions {
            renderer: eframe::Renderer::Wgpu,
            // Saved minimized-window geometry can be tiny on Windows and
            // overrides the builder's maximized flag. Stop saving geometry;
            // existing saves are overridden after creation below. Account and
            // settings persistence remain independent.
            persist_window: false,
            viewport,
            ..Default::default()
        },
        Box::new(move |creation| {
            if fixture.is_none() {
                // eframe still loads old geometry with persist_window=false,
                // and initial maximization can be lost while mapping a hidden
                // window. Apply once after creation, never on every repaint.
                creation
                    .egui_ctx
                    .send_viewport_cmd(egui::ViewportCommand::Fullscreen(false));
                creation
                    .egui_ctx
                    .send_viewport_cmd(egui::ViewportCommand::Maximized(true));
            }
            let mut app = CaperApp::new(&creation.egui_ctx, api, fixture.as_deref());
            motion::watch_reduced(&creation.egui_ctx);
            if let Some(storage) = creation.storage {
                app.restore_preferences(storage);
            }
            if fixture.is_none() {
                let context = creation.egui_ctx.clone();
                app.app_links = app_link::listen(move || context.request_repaint());
            }
            app.pending_invite = launch_invite;
            if fixture.is_none() {
                app.daily_icon = Some(daily_icon::DailyIcon::load(creation.storage));
            }
            Ok(Box::new(app))
        }),
    )
}

