    #[test]
    fn pins_cards_align_navigation_and_keep_close_visible_in_small_windows() {
        for size in [egui::vec2(840.0, 620.0), egui::vec2(390.0, 520.0)] {
            let context = egui::Context::default();
            context.all_styles_mut(|style| style.animation_time = 0.0);
            let mut app = CaperApp::new(
                &context,
                crate::api::Api::new("http://127.0.0.1:9").unwrap(),
                Some("parity-pins"),
            );
            let frame = |app: &mut CaperApp, screen_size, events| {
                context.run(
                    egui::RawInput {
                        screen_rect: Some(egui::Rect::from_min_size(egui::Pos2::ZERO, screen_size)),
                        events,
                        ..Default::default()
                    },
                    |context| app.page(context),
                )
            };
            for _ in 0..3 {
                frame(&mut app, egui::vec2(1440.0, 900.0), vec![]);
            }
            for _ in 0..3 {
                frame(&mut app, size, vec![]);
            }
            context.enable_accesskit();
            let output = frame(&mut app, size, vec![]);
            let nodes = &output
                .platform_output
                .accesskit_update
                .as_ref()
                .unwrap()
                .nodes;
            let bounds = |label| {
                nodes
                    .iter()
                    .find_map(|(_, node)| {
                        (node.label() == Some(label))
                            .then(|| node.bounds())
                            .flatten()
                    })
                    .unwrap_or_else(|| panic!("missing {label} at {size:?}"))
            };
            let close = bounds("Close pins");
            let author = output
                .shapes
                .iter()
                .rev()
                .find_map(|shape| match &shape.shape {
                    egui::Shape::Text(text) if text.galley.job.text == "Fixture Owner" => {
                        Some(egui::Rect::from_min_size(text.pos, text.galley.size()))
                    }
                    _ => None,
                })
                .unwrap();
            let go = bounds("Go to message");
            assert!(
                go.y0 > f64::from(author.bottom()),
                "navigation follows the message"
            );
            assert!(
                close.x0 > f64::from(author.right()) && close.y1 < f64::from(author.top()),
                "close belongs in the top-right header"
            );
            for button in [close, go] {
                assert!(button.x0 >= 0.0 && button.x1 <= f64::from(size.x));
                assert!(button.y0 >= 0.0 && button.y1 <= f64::from(size.y));
            }
            let navigation_rect = egui::Rect::from_min_max(
                egui::pos2(go.x0 as f32, go.y0 as f32),
                egui::pos2(go.x1 as f32, go.y1 as f32),
            );
            let navigation_clip = output
                .shapes
                .iter()
                .find_map(|shape| match &shape.shape {
                    egui::Shape::Text(text) if text.galley.job.text == "Go to message" => {
                        Some(shape.clip_rect)
                    }
                    _ => None,
                })
                .unwrap();
            assert!(
                navigation_clip.contains_rect(navigation_rect),
                "navigation is clipped at {size:?}: {navigation_rect:?} by {navigation_clip:?}"
            );
            assert!(
                !output.shapes.iter().any(|shape| matches!(&shape.shape,
                    egui::Shape::Text(text) if text.galley.job.text == "Reply in thread"
                        && shape.clip_rect == navigation_clip
                )),
                "Pins must not show a redundant static reply button"
            );
            let navigation_center = egui::pos2(
                ((go.x0 + go.x1) / 2.0) as f32,
                ((go.y0 + go.y1) / 2.0) as f32,
            );
            let card = output
                .shapes
                .iter()
                .find_map(|shape| match &shape.shape {
                    egui::Shape::Rect(rect)
                        if rect.fill == egui::Color32::from_rgba_unmultiplied(182, 77, 50, 31)
                            && f64::from(rect.rect.top()) > close.y1
                            && rect.rect.contains(author.center())
                            && rect.rect.contains(navigation_center)
                            && shape.clip_rect.contains_rect(rect.rect) =>
                    {
                        Some(rect)
                    }
                    _ => None,
                })
                .expect("one continuous pin wash covers the message and navigation");
            assert_eq!(card.stroke.width, 0.0, "the card has no extra border");
            assert!(
                (go.x1 - f64::from(card.rect.right() - 18.0)).abs() < 1.0,
                "navigation aligns with the card's trailing inset"
            );
            assert!(
                (go.y1 - f64::from(card.rect.bottom() - 20.0)).abs() < 1.0,
                "navigation sits at the card bottom without expanding the footer"
            );
            assert!(go.height() >= 32.0, "navigation is a full button target");
            assert!(
                output.shapes.iter().any(|shape| matches!(&shape.shape,
                    egui::Shape::Rect(rect) if rect.stroke.width == 1.0
                        && rect.rect.contains(navigation_center)
                        && !rect.rect.contains(author.center())
                )),
                "navigation has its own button frame"
            );
            for pressed in [true, false] {
                frame(
                    &mut app,
                    size,
                    vec![
                        egui::Event::PointerMoved(egui::pos2(
                            (close.x0 + 14.0) as f32,
                            (close.y0 + 14.0) as f32,
                        )),
                        egui::Event::PointerButton {
                            pos: egui::pos2((close.x0 + 14.0) as f32, (close.y0 + 14.0) as f32),
                            button: egui::PointerButton::Primary,
                            pressed,
                            modifiers: egui::Modifiers::NONE,
                        },
                    ],
                );
            }
            assert!(!app.showing_pins, "header close works at {size:?}");
        }
    }

    #[test]
    fn update_review_isolates_composer_and_dismisses_with_escape_or_backdrop() {
        let context = egui::Context::default();
        let mut app = CaperApp::new(
            &context,
            crate::api::Api::new("http://127.0.0.1:9").unwrap(),
            Some("parity-update"),
        );
        app.updates.dismiss();
        app.draft = "Keep this draft".into();
        render(&mut app, &context, vec![]);
        context.memory_mut(|memory| memory.request_focus(egui::Id::new("message-composer")));
        app.updates.show_available();
        let frame = |app: &mut CaperApp, events| {
            context.run(
                egui::RawInput {
                    screen_rect: Some(egui::Rect::from_min_size(
                        egui::Pos2::ZERO,
                        egui::vec2(960.0, 540.0),
                    )),
                    events,
                    dropped_files: vec![egui::DroppedFile {
                        path: Some(std::path::PathBuf::from("/tmp/update-review-drop.txt")),
                        ..Default::default()
                    }],
                    ..Default::default()
                },
                |context| {
                    app.update_notice(context);
                    app.page(context);
                },
            )
        };
        let key = |key| egui::Event::Key {
            key,
            physical_key: None,
            pressed: true,
            repeat: false,
            modifiers: egui::Modifiers::NONE,
        };
        for _ in 0..4 {
            frame(&mut app, vec![]);
        }
        frame(
            &mut app,
            vec![
                egui::Event::Text("must not type".into()),
                key(egui::Key::Enter),
            ],
        );
        assert_eq!(app.draft, "Keep this draft");
        assert!(app.pending.is_none());
        assert!(app.draft_files.is_empty(), "review must not accept drops");
        assert!(!context.memory(|memory| memory.has_focus(egui::Id::new("message-composer"))));
        frame(&mut app, vec![]);
        app.updates.show_available();
        for _ in 0..4 {
            frame(&mut app, vec![]);
        }
        assert!(app.updates.available().is_some());
        frame(
            &mut app,
            vec![
                key(egui::Key::Escape),
                egui::Event::Text("nor on dismissal".into()),
            ],
        );
        assert!(app.updates.available().is_none());
        assert!(app.updates.known_available().is_some());
        assert_eq!(app.draft, "Keep this draft");
        frame(&mut app, vec![]);
        app.updates.show_available();
        for _ in 0..4 {
            frame(&mut app, vec![]);
        }
        let pos = egui::pos2(2.0, 2.0);
        for pressed in [true, false] {
            frame(
                &mut app,
                vec![
                    egui::Event::PointerMoved(pos),
                    egui::Event::PointerButton {
                        pos,
                        button: egui::PointerButton::Primary,
                        pressed,
                        modifiers: egui::Modifiers::NONE,
                    },
                ],
            );
        }
        assert!(app.updates.available().is_none());
        assert_eq!(app.draft, "Keep this draft");
    }

    #[test]
    fn account_update_action_survives_later_and_reopens_review_without_installing() {
        for (fixture, sidebar_width, scale) in [
            ("parity-update", 220.0),
            ("parity-update", 440.0),
            ("parity-update-download", 220.0),
            ("parity-update-download", 440.0),
        ]
        .into_iter()
        .flat_map(|(fixture, width)| {
            [1.0, 1.25, 1.5, 2.0].map(move |scale| (fixture, width, scale))
        }) {
            let context = egui::Context::default();
            context.set_pixels_per_point(scale);
            context.enable_accesskit();
            let mut app = CaperApp::new(
                &context,
                crate::api::Api::new("http://127.0.0.1:9").unwrap(),
                Some(fixture),
            );
            app.sidebar_width = sidebar_width;
            app.updates.dismiss();
            render(&mut app, &context, vec![]);
            let output = render(&mut app, &context, vec![]);
            let bounds = output
                .platform_output
                .accesskit_update
                .as_ref()
                .unwrap()
                .nodes
                .iter()
                .find(|(_, node)| node.label() == Some("Update available"))
                .unwrap()
                .1
                .bounds()
                .unwrap();
            // A known update remains visible; it never hides behind the profile.
            for time in [0.15, 1.5, 6.5, 15.0] {
                let output = context.run(
                    egui::RawInput {
                        screen_rect: Some(egui::Rect::from_min_size(
                            egui::Pos2::ZERO,
                            egui::vec2(1440.0, 900.0),
                        )),
                        time: Some(time),
                        ..Default::default()
                    },
                    |context| app.page(context),
                );
                let current = output
                    .platform_output
                    .accesskit_update
                    .as_ref()
                    .unwrap()
                    .nodes
                    .iter()
                    .find(|(_, node)| node.label() == Some("Update available"))
                    .unwrap()
                    .1
                    .bounds()
                    .unwrap();
                assert_eq!(current, bounds, "update button moved at {time}s");
                assert!(output.shapes.iter().any(|shape| matches!(&shape.shape,
                    egui::Shape::Text(text) if text.galley.job.text == "Update available"
                        && shape.clip_rect.contains_rect(egui::Rect::from_min_size(text.pos, text.galley.size()))
                )), "update label clipped at {time}s");
                let button_center = ((current.x0 + current.x1) / 2.0) as f32;
                assert!(
                    output.shapes.iter().any(|shape| matches!(&shape.shape,
                        egui::Shape::Text(text) if text.galley.job.text == "Update available"
                            && (text.visual_bounding_rect().center().x - button_center).abs() <= 1.0
                    )),
                    "update glyphs are not centered at sidebar width {sidebar_width}, scale {scale}, {time}s"
                );
                for label in [
                    "Edit profile for Fixture Owner",
                    "Mute microphone",
                    "Deafen audio",
                    "User Settings",
                ] {
                    let control = output
                        .platform_output
                        .accesskit_update
                        .as_ref()
                        .unwrap()
                        .nodes
                        .iter()
                        .find(|(_, node)| node.label() == Some(label))
                        .unwrap_or_else(|| panic!("missing {label}"))
                        .1
                        .bounds()
                        .unwrap();
                    assert!(control.y0 >= current.y1, "update overlaps {label}");
                    assert!(control.y1 <= 900.0, "{label} is offscreen");
                }
            }
            let pos = egui::pos2(
                (bounds.x0 + bounds.x1) as f32 / 2.0,
                (bounds.y0 + bounds.y1) as f32 / 2.0,
            );
            let output = click_at(&mut app, &context, pos);
            assert_eq!(app.updates.available().unwrap().version, "0.1.42");
            assert!(app.updates.error.is_none());
            assert!(
                output.platform_output.commands.is_empty(),
                "review must not download or install"
            );
            assert!(
                output
                    .viewport_output
                    .values()
                    .all(|viewport| !viewport.commands.contains(&egui::ViewportCommand::Close))
            );
            let mut output = egui::FullOutput::default();
            for _ in 0..4 {
                output = context.run(
                    egui::RawInput {
                        screen_rect: Some(egui::Rect::from_min_size(
                            egui::Pos2::ZERO,
                            egui::vec2(1440.0, 900.0),
                        )),
                        ..Default::default()
                    },
                    |context| app.update_notice(context),
                );
            }
            assert!(output.shapes.iter().any(|shape| matches!(&shape.shape,
                egui::Shape::Text(text) if text.galley.job.text == "A fresh Caper is ready")));
        }
    }

    #[test]
    fn failed_update_error_is_sent_to_the_caper_team_from_your_notes() {
        let context = egui::Context::default();
        let mut app = CaperApp::new(
            &context,
            crate::api::Api::new("http://127.0.0.1:9").unwrap(),
            Some("parity-update-error"),
        );
        // Fixtures never sign in; the report needs a session like the real app.
        app.token = Some("fixture-token".into());
        let (events, receiver) = std::sync::mpsc::channel();
        app.worker.events = receiver;
        let frame = |app: &mut CaperApp, events| {
            context.run(
                egui::RawInput {
                    screen_rect: Some(egui::Rect::from_min_size(
                        egui::Pos2::ZERO,
                        egui::vec2(1440.0, 900.0),
                    )),
                    events,
                    ..Default::default()
                },
                |context| app.update_notice(context),
            )
        };
        let shows = |output: &egui::FullOutput, label: &str| {
            output.shapes.iter().any(|shape| {
                matches!(&shape.shape, egui::Shape::Text(text) if text.galley.job.text == label)
            })
        };
        for _ in 0..5 {
            frame(&mut app, vec![]);
        }
        let output = frame(&mut app, vec![]);
        let button = text_position(&output, "Send this to the Caper team");
        for pressed in [true, false] {
            frame(
                &mut app,
                vec![
                    egui::Event::PointerMoved(button),
                    egui::Event::PointerButton {
                        pos: button,
                        button: egui::PointerButton::Primary,
                        pressed,
                        modifiers: egui::Modifiers::NONE,
                    },
                ],
            );
        }
        let report = app.update_report.as_ref().expect("report started");
        assert!(matches!(report.state, crate::ReportState::Sending));
        let client_id = report.client_id.clone();
        let own = app.account.as_ref().unwrap().id.clone();
        assert!(shows(
            &frame(&mut app, vec![]),
            "Sending to the Caper team…"
        ));

        let send = |client_id: &str| {
            Box::new(crate::profile_dm::Send {
                person: own.clone(),
                username: "owner".into(),
                name: "Owner".into(),
                client_id: client_id.into(),
                text: String::new(),
                files: Vec::new(),
                settings: None,
                cancel: std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false)),
                retrying: false,
                open_only: false,
                direct: None,
            })
        };
        events
            .send(crate::worker::Event::ProfileSent {
                epoch: app.account_epoch,
                person: own.clone(),
                send: send(&client_id),
                result: Err(crate::profile_dm::Failure {
                    message: "Local test refusal".into(),
                    uncertain: false,
                }),
            })
            .unwrap();
        app.receive();
        let output = frame(&mut app, vec![]);
        assert!(shows(&output, "Local test refusal"));
        assert!(shows(&output, "Send this to the Caper team"), "can retry");
        assert!(
            app.profile_drafts.is_empty(),
            "no profile draft side effects"
        );

        app.send_update_report(
            "Could not replace the installed app: Access denied (os error 5)".into(),
            "0.1.42",
        );
        let client_id = app.update_report.as_ref().unwrap().client_id.clone();
        let notes: crate::model::DirectConversation = serde_json::from_value(serde_json::json!({
            "id": "dm-notes", "peer": {"id": own, "username": "owner", "displayName": "Owner"},
            "lastSeq": "1", "readSeq": "1", "status": "accepted"
        }))
        .unwrap();
        events
            .send(crate::worker::Event::ProfileSent {
                epoch: app.account_epoch,
                person: own.clone(),
                send: send(&client_id),
                result: Ok(notes),
            })
            .unwrap();
        app.receive();
        assert!(shows(
            &frame(&mut app, vec![]),
            "Sent. The Caper team will reply in your notes."
        ));
        assert!(app.updates.available().is_some(), "the review stays open");
        assert!(
            app.selected_direct.is_none(),
            "no navigation behind the dialog"
        );
        assert!(app.directs.iter().any(|direct| direct.id == "dm-notes"));
    }

