    #[test]
    fn update_download_button_opens_the_platform_installer() {
        for (fixture, label) in [
            ("parity-update-download", "Download"),
            ("parity-update-error", "use the installer"),
        ] {
            let context = egui::Context::default();
            let mut app = CaperApp::new(
                &context,
                crate::api::Api::new("http://127.0.0.1:9").unwrap(),
                Some(fixture),
            );
            let mut frame = |events| {
                context.run(
                    egui::RawInput {
                        screen_rect: Some(egui::Rect::from_min_size(
                            egui::Pos2::ZERO,
                            egui::vec2(1440.0, 900.0),
                        )),
                        events,
                        ..Default::default()
                    },
                    |context| app.update_notice(context),
                )
            };
            // Let the window and its nested scroll area finish egui's sizing passes.
            for _ in 0..3 {
                frame(vec![]);
            }
            let output = frame(vec![]);
            let pos = text_position(&output, label);
            for pressed in [true, false] {
                let output = frame(vec![
                    egui::Event::PointerMoved(pos),
                    egui::Event::PointerButton {
                        pos,
                        button: egui::PointerButton::Primary,
                        pressed,
                        modifiers: egui::Modifiers::NONE,
                    },
                ]);
                let opened = output.platform_output.commands.iter().find_map(|command| {
                    if let egui::OutputCommand::OpenUrl(url) = command {
                        Some(url.url.as_str())
                    } else {
                        None
                    }
                });
                let expected = if cfg!(windows) {
                    "https://github.com/joswayski/caper/releases/download/native-latest/Caper-Windows-x64-Setup.exe"
                } else {
                    "https://github.com/joswayski/caper/releases/download/native-latest/Caper-Linux-x64.deb"
                };
                assert_eq!(opened, (!pressed).then_some(expected));
            }
        }
    }

    #[test]
    fn update_actions_stay_visible_before_and_after_scrolling_at_small_sizes() {
        for size in [
            egui::vec2(320.0, 560.0),
            egui::vec2(390.0, 600.0),
            egui::vec2(960.0, 540.0),
            egui::vec2(1440.0, 900.0),
        ] {
            for fixture in [
                "parity-update",
                "parity-update-download",
                "parity-update-error",
                "parity-update-incomplete",
                "parity-update-in-call",
            ] {
                let context = egui::Context::default();
                let mut app = CaperApp::new(
                    &context,
                    crate::api::Api::new("http://127.0.0.1:9").unwrap(),
                    Some(fixture),
                );
                let screen = egui::Rect::from_min_size(egui::Pos2::ZERO, size);
                let mut time = 0.0;
                let mut frame = |events| {
                    time += 1.0 / 60.0;
                    context.run(
                        egui::RawInput {
                            screen_rect: Some(screen),
                            time: Some(time),
                            events,
                            ..Default::default()
                        },
                        |context| app.update_notice(context),
                    )
                };
                let visible = |output: &egui::FullOutput, label: &str| {
                    output.shapes.iter().any(|shape| {
                        if let egui::Shape::Text(text) = &shape.shape {
                            let rect = egui::Rect::from_min_size(text.pos, text.galley.size());
                            text.galley.job.text == label
                                && screen.contains_rect(rect)
                                && shape.clip_rect.contains_rect(rect)
                        } else {
                            false
                        }
                    })
                };
                // The modal and its two nested scroll areas take a few frames to size.
                for _ in 0..5 {
                    frame(vec![]);
                }
                let initial = frame(vec![]);
                let action = if fixture == "parity-update-download" {
                    "Download"
                } else if fixture == "parity-update-in-call" {
                    "Restart and leave call"
                } else {
                    "Restart to update"
                };
                assert!(
                    visible(&initial, action),
                    "{fixture} {size:?}: action clipped before scrolling"
                );
                assert!(
                    visible(&initial, "Later"),
                    "{fixture} {size:?}: Later clipped"
                );
                assert!(
                    visible(&initial, "Voice moves into the channel list"),
                    "notes start expanded"
                );
                assert!(
                    visible(&initial, "October 18, 2026"),
                    "date replaces the version"
                );
                assert!(!visible(&initial, "0.1.42"), "no version numbers");
                assert!(
                    !visible(&initial, "Having issues? Download installer instead"),
                    "the installer lives in the error sentence only"
                );
                if fixture == "parity-update-error" {
                    assert!(visible(&initial, "The last update didn’t finish"));
                    assert!(visible(&initial, "use the installer"));
                }
                let expanded = initial;
                assert!(
                    visible(&expanded, action),
                    "expanded action clipped: {fixture} {size:?}"
                );
                let action_pos = text_position(&expanded, action);
                let notes_pos = text_position(&expanded, "Voice moves into the channel list");
                let mut scrolled = expanded;
                // At narrow widths a single entry is taller than the notes
                // viewport; scrolling straight to the bottom hides its heading.
                for _ in 0..100 {
                    if visible(&scrolled, "Forwarded messages open in their thread") {
                        break;
                    }
                    frame(vec![
                        egui::Event::PointerMoved(notes_pos),
                        egui::Event::MouseWheel {
                            unit: egui::MouseWheelUnit::Point,
                            delta: egui::vec2(0.0, -40.0),
                            modifiers: egui::Modifiers::NONE,
                        },
                    ]);
                    for _ in 0..4 {
                        scrolled = frame(vec![]);
                    }
                }
                assert!(
                    visible(&scrolled, "Forwarded messages open in their thread"),
                    "{fixture} {size:?}: last highlight cannot be reached"
                );
                assert!(visible(&scrolled, action));
                assert_eq!(
                    text_position(&scrolled, action),
                    action_pos,
                    "{fixture} {size:?}: scroll moved the action footer"
                );
                let later = text_position(&scrolled, "Later");
                for pressed in [true, false] {
                    frame(vec![
                        egui::Event::PointerMoved(later),
                        egui::Event::PointerButton {
                            pos: later,
                            button: egui::PointerButton::Primary,
                            pressed,
                            modifiers: egui::Modifiers::NONE,
                        },
                    ]);
                }
                assert!(
                    app.updates.available().is_none(),
                    "Later must still work after scrolling"
                );
            }
        }
    }

    #[test]
    fn whats_new_defers_until_workspace_ready_without_call_or_other_modal() {
        for blocker in 0..8 {
            let context = egui::Context::default();
            let mut app = CaperApp::new(
                &context,
                crate::api::Api::new("http://127.0.0.1:9").unwrap(),
                Some("parity-whats-new"),
            );
            app.whats_new.dismiss(); // Fixture has not drawn/acknowledged its unread snapshot.
            app.dialog = None;
            app.foreground = true;
            let account = app.account.clone();
            match blocker {
                0 => app.foreground = false,
                1 => app.account = None,
                2 => app.loading = true,
                3 => app.restoring = Some(Instant::now()),
                4 => app.opening = true,
                5 => app.dialog = Some(Dialog::Settings),
                6 => app.showing_pins = true,
                7 => {
                    app.voice.state.phase = Phase::Connected(crate::state::CallContext {
                        channel_id: "voice".into(),
                        channel_name: "Voice".into(),
                        space_name: "Fixture".into(),
                    })
                }
                _ => unreachable!(),
            }
            app.poll_whats_new(&context);
            assert!(
                !matches!(app.dialog, Some(Dialog::WhatsNew)),
                "blocker {blocker}"
            );
            app.foreground = true;
            app.account = account;
            app.loading = false;
            app.restoring = None;
            app.opening = false;
            app.dialog = None;
            app.showing_pins = false;
            app.voice.state.phase = Phase::Idle;
            app.poll_whats_new(&context);
            assert!(
                matches!(app.dialog, Some(Dialog::WhatsNew)),
                "unread snapshot retained for blocker {blocker}"
            );
        }
    }

    #[test]
    fn whats_new_dismissals_acknowledge_and_settings_reopens_newest_first() {
        for route in ["Done", "Close What’s new", "Escape", "backdrop"] {
            let context = egui::Context::default();
            context.enable_accesskit();
            let mut app = CaperApp::new(
                &context,
                crate::api::Api::new("http://127.0.0.1:9").unwrap(),
                Some("parity-whats-new"),
            );
            for _ in 0..3 {
                render(&mut app, &context, vec![]);
            }
            let output = render(&mut app, &context, vec![]);
            assert!(
                text_position(&output, "Edit your messages").y
                    < text_position(&output, "Find your conversations").y
            );
            match route {
                "Escape" => {
                    render(&mut app, &context, press(egui::Key::Escape));
                }
                "backdrop" => click(&mut app, &context, egui::pos2(10.0, 10.0)),
                "Done" => click(&mut app, &context, text_position(&output, "Done")),
                _ => click(&mut app, &context, node_center(&output, route)),
            }
            assert!(app.dialog.is_none(), "{route}");
            assert!(
                !app.whats_new.open_unread(),
                "{route} acknowledges the shown snapshot"
            );
            app.dialog = Some(Dialog::Settings);
            for _ in 0..3 {
                render(&mut app, &context, vec![]);
            }
            let pos = scrolled_text_position(&mut app, &context, "What’s new");
            click(&mut app, &context, pos);
            assert!(matches!(app.dialog, Some(Dialog::WhatsNew)));
            for _ in 0..3 {
                render(&mut app, &context, vec![]);
            }
            let output = render(&mut app, &context, vec![]);
            assert!(
                shows(&output, "Edit your messages"),
                "manual history includes acknowledged releases"
            );
            assert!(shows(&output, "Find your conversations"));
        }
    }

