    #[test]
    fn blocked_accounts_load_failures_offer_try_again_and_never_claim_an_empty_list() {
        use crate::worker::AccountResult;
        let context = egui::Context::default();
        let mut app = CaperApp::new(
            &context,
            crate::api::Api::new("http://127.0.0.1:9").unwrap(),
            Some("parity-settings"),
        );
        app.token = Some("account-token".into());
        for loaded in [None, Some(Vec::new())] {
            app.blocks = loaded;
            app.account_result(AccountResult::Blocks(Err("Could not reach Caper.".into())));
            render(&mut app, &context, vec![]);
            let output = scroll_modal_to_bottom(&mut app, &context);
            let labels = texts(&output);
            assert!(labels.contains(&"Could not reach Caper."), "{labels:?}");
            for hidden in ["Loading…", "You haven't blocked anyone."] {
                assert!(!labels.contains(&hidden), "{hidden}: {labels:?}");
            }
            click(&mut app, &context, text_position(&output, "Try again"));
            assert!(app.blocks_error.is_none(), "Try again reloads");
        }
        app.account_result(AccountResult::Blocks(Err("Could not reach Caper.".into())));
        app.account_result(AccountResult::Blocks(Ok(Vec::new())));
        assert!(
            app.blocks_error.is_none(),
            "a successful load clears the error"
        );
        let output = scroll_modal_to_bottom(&mut app, &context);
        assert!(texts(&output).contains(&"You haven't blocked anyone."));
    }

    #[test]
    fn live_rooms_say_who_is_there_and_join_without_navigating_or_playback_controls() {
        let context = egui::Context::default();
        let mut app = CaperApp::new(
            &context,
            crate::api::Api::new("http://127.0.0.1:9").unwrap(),
            Some("parity-voice-rosters"),
        );
        app.token = Some("fixture-only".into());
        let selected = app.selected_channel.clone();
        let (target, space) = app.voice_target("chan00000002").unwrap();
        assert_eq!(target.channel_name, "design");
        assert_eq!(target.channel_id, "chan00000002");
        assert_eq!(space.as_deref(), Some("space0000001"));
        assert_eq!(app.selected_channel, selected);
        assert!(app.voice_target("not-in-space").is_none());
        render(&mut app, &context, vec![]);
        let started = std::time::Instant::now();
        while context.has_pending_images() {
            assert!(started.elapsed() < std::time::Duration::from_secs(30));
            std::thread::sleep(std::time::Duration::from_millis(10));
            render(&mut app, &context, vec![]);
        }
        let output = render(&mut app, &context, vec![]);
        let sidebar_text = |output: &egui::FullOutput, label: &str| {
            output.shapes.iter().find_map(|shape| match &shape.shape {
                egui::Shape::Text(text) if text.pos.x < 340.0 && text.galley.job.text == label => {
                    Some(text.pos)
                }
                _ => None,
            })
        };
        // The live row grows into its card in place under the Channels
        // heading: no "Live now" and no count of rooms.
        assert!(sidebar_text(&output, "Live now").is_none());
        assert!(sidebar_text(&output, "2 rooms").is_none());
        let channels = sidebar_text(&output, "Channels").expect("Channels heading");
        let row = node_bounds(&output, "design").unwrap();
        let names = sidebar_text(&output, "Maya and Alex").expect("the room's names");
        assert!(channels.y < row.top() && row.bottom() < names.y);
        let card = output
            .shapes
            .iter()
            .find_map(|shape| match &shape.shape {
                egui::Shape::Rect(rect)
                    if rect.fill == super::ROOM_CARD
                        && rect.stroke.color == super::ROOM_CARD_BORDER =>
                {
                    Some(rect.rect)
                }
                _ => None,
            })
            .expect("the room's card");
        assert!(card.contains_rect(row) && card.contains(names));
        let general = node_bounds(&output, "general").unwrap();
        let planning = node_bounds(&output, "planning").unwrap();
        assert!(general.bottom() < card.top() && card.bottom() < planning.top());
        // The row counts who is there; the card's body names them.
        assert!(sidebar_text(&output, "Maya").is_none());
        let live = node_bounds(&output, "2 in voice").expect("the row's live count");
        assert!(row.contains_rect(live), "{live:?} in {row:?}");
        // The session's timer sits in the body, between the names and Join.
        let (timer, timer_bounds) = output
            .platform_output
            .accesskit_update
            .as_ref()
            .unwrap()
            .nodes
            .iter()
            .find_map(|(_, node)| {
                node.value()
                    .filter(|value| value.starts_with("Voice session duration: "))
                    .map(|value| (value.to_owned(), node.bounds().unwrap()))
            })
            .expect("the room's timer");
        assert!(
            timer.ends_with("28:21") || timer.ends_with("28:22"),
            "{timer}"
        );
        let join = node_bounds(&output, "Join #design").unwrap();
        assert!(
            f64::from(names.x) < timer_bounds.x0
                && timer_bounds.x1 <= f64::from(join.left())
                && timer_bounds.y0 > f64::from(row.bottom()),
            "{timer_bounds:?}"
        );
        // Spectators never get playback controls.
        for hidden in ["Audio", "User volume", "Mute for me"] {
            assert!(!texts(&output).contains(&hidden), "{hidden}");
        }
        // Join keeps the open conversation; anywhere else on the card opens
        // the room's chat.
        click(&mut app, &context, join.center());
        assert_eq!(
            app.pending_voice_join
                .as_ref()
                .map(|(channel, _, _)| channel.as_str()),
            Some("chan00000002")
        );
        assert_eq!(app.selected_channel, selected);
        assert!(app.navigation_target.is_none());
        let joining = render(&mut app, &context, vec![]);
        assert!(texts(&joining).contains(&"Joining…"));
        assert!(node_bounds(&joining, "Join #design").is_none());
        assert!(matches!(app.voice.state.phase, Phase::Idle));
        // The busy button is no way through to the chat either.
        click(&mut app, &context, node_center(&joining, "Joining #design"));
        assert!(app.navigation_target.is_none());
        click(&mut app, &context, names + egui::vec2(4.0, 6.0));
        assert_eq!(
            app.navigation_target
                .as_ref()
                .and_then(|target| target.channel.as_deref()),
            Some("chan00000002")
        );
    }

    #[test]
    fn denied_voice_switch_preserves_call_and_leave_fences_late_permission() {
        let context = egui::Context::default();
        let mut app = CaperApp::new(
            &context,
            crate::api::Api::new("http://127.0.0.1:9").unwrap(),
            Some("parity-voice-rosters"),
        );
        app.token = Some("fixture-only".into());
        let (original, _) = app.voice_target("chan00000001").unwrap();
        app.voice.state.phase = Phase::Connected(original.clone());
        let chat = app.selected_channel.clone();
        app.voice_join_request = 7;
        app.pending_voice_join = Some(("chan00000002".into(), 0, 12_345));
        app.accept_voice_target(
            7,
            0,
            "space0000001",
            "chan00000002",
            Err(LoadError {
                message: "Denied target".into(),
                access_denied: true,
                space_access_denied: false,
            }),
        );
        assert_eq!(app.voice.state.phase, Phase::Connected(original.clone()));
        assert_eq!(app.selected_channel, chat);
        assert!(app.voice_target("chan00000002").is_none());
        app.accept_voice_target(6, 0, "space0000001", "chan00000003", Ok(()));
        assert_eq!(app.voice.state.phase, Phase::Connected(original));
        app.voice.leave();
        app.accept_voice_target(7, 0, "space0000001", "chan00000003", Ok(()));
        assert_eq!(app.voice.state.phase, Phase::Idle);
        app.voice.state.phase = Phase::Failed(app.voice_target("chan00000003").unwrap().0);
        app.join_voice_channel("chan00000003");
        assert_eq!(app.voice_join_request, 8, "A failed join must be retryable");
        assert_eq!(app.selected_channel, chat);
    }

    #[test]
    fn roster_epochs_and_revocation_keep_late_private_occupancy_out_of_chat() {
        let context = egui::Context::default();
        let mut app = CaperApp::new(
            &context,
            crate::api::Api::new("http://127.0.0.1:9").unwrap(),
            Some("parity-voice-rosters"),
        );
        let people = app.channel_rosters["chan00000002"].clone();
        app.token = Some("fixture-only".into());
        let (target, _) = app.voice_target("chan00000002").unwrap();
        app.voice.state.phase = Phase::Connected(target);
        let selected = app.selected_channel.clone();
        app.roster_generation = 42;
        app.gateway(GatewayEvent::VoiceUnavailable {
            generation: 41,
            channel: "chan00000002".into(),
            revoked: true,
        });
        assert!(app.channel_rosters.contains_key("chan00000002"));
        app.gateway(GatewayEvent::VoiceUnavailable {
            generation: 42,
            channel: "chan00000002".into(),
            revoked: false,
        });
        assert!(!app.channel_rosters.contains_key("chan00000002"));
        assert!(
            matches!(app.voice.state.phase, Phase::Connected(_)),
            "A spectator service failure is not call revocation"
        );
        app.gateway(GatewayEvent::VoiceUnavailable {
            generation: 42,
            channel: "chan00000002".into(),
            revoked: true,
        });
        assert!(app.voice.state.active_channel().is_none());
        assert!(app.voice_target("chan00000002").is_none());
        assert_eq!(app.selected_channel, selected);
        app.clear_channel_state();
        app.gateway(GatewayEvent::VoiceRoster {
            generation: 42,
            channel: "chan00000002".into(),
            participants: people.clone(),
            session_started_at: Some(1_000),
        });
        assert!(app.channel_rosters.is_empty());
        assert!(app.voice_session_starts.is_empty());
        app.selected_channel = selected;
        app.gateway(GatewayEvent::VoiceRoster {
            generation: 43,
            channel: "chan00000003".into(),
            participants: people,
            session_started_at: Some(5_000),
        });
        assert!(app.channel_rosters.contains_key("chan00000003"));
        assert_eq!(app.voice_session_starts["chan00000003"], 5_000);
        app.gateway(GatewayEvent::VoiceReset { generation: 42 });
        assert!(!app.channel_rosters.is_empty());
        app.gateway(GatewayEvent::VoiceReset { generation: 43 });
        assert!(app.channel_rosters.is_empty());
        assert!(app.voice_session_starts.is_empty());
    }

    #[test]
    fn secondary_clicks_on_call_faces_open_the_full_list_whose_audio_changes_only_that_listener() {
        let context = egui::Context::default();
        let mut app = CaperApp::new(
            &context,
            crate::api::Api::new("http://127.0.0.1:9").unwrap(),
            Some("parity-voice-connected"),
        );
        // Another chat is open, so opening the call's would show.
        app.selected_channel = Some("chan00000003".into());
        render(&mut app, &context, vec![]);
        let output = render(&mut app, &context, vec![]);
        // You first, then the others, in one row of faces in the card.
        let faces: Vec<_> = ["Fixture Owner (you)", "Maya", "Alex"]
            .into_iter()
            .map(|label| node_bounds(&output, label).unwrap_or_else(|| panic!("missing {label}")))
            .collect();
        for pair in faces.windows(2) {
            assert!(pair[0].right() < pair[1].left() && pair[0].top() == pair[1].top());
        }
        assert_eq!(faces[0].size(), egui::vec2(36.0, 36.0));
        assert!(faces[2].right() <= 327.0, "faces stay inside the card");
        assert!(texts(&output).contains(&"3 people"));
        assert!(!texts(&output).contains(&"User volume"));
        // A face is no button of its own: a click opens the call's chat,
        // as the rest of the card does.
        click(&mut app, &context, faces[1].center());
        assert!(app.call_list.is_none());
        assert_eq!(
            app.navigation_target
                .as_ref()
                .and_then(|target| target.channel.as_deref()),
            Some("chan00000001")
        );
        app.navigation_target = None;
        app.opening = false;
        app.voice.set_participant_playback(
            "fixture-maya",
            crate::media::TrackPlayback {
                gain_percent: 170,
                muted: false,
            },
        );
        // A right-click on another person's face opens the list at their
        // audio controls, without opening the chat.
        secondary_click(&mut app, &context, faces[1].center());
        assert_eq!(
            app.call_list,
            Some(super::CallList {
                audio: Some("fixture-maya".into())
            })
        );
        assert!(app.navigation_target.is_none());
        let list = render(&mut app, &context, vec![]);
        let shown = texts(&list);
        for label in [
            "In #general · 3 people",
            "User volume",
            "170%",
            "Mute for me",
        ] {
            assert!(shown.contains(&label), "{label}: {shown:?}");
        }
        assert_eq!(
            shown.iter().filter(|text| **text == "Audio").count(),
            2,
            "only remote participants have Audio buttons"
        );
        let heading = text_position(&list, "In #general · 3 people");
        assert!(heading.x > 340.0, "the list opens beside the sidebar");
        click(&mut app, &context, text_position(&list, "Mute for me"));
        assert!(app.voice.playback("fixture-maya").muted);
        assert!(!app.voice.playback("fixture-alex").muted);
        assert!(
            !app.voice.state.audio.muted,
            "local listener control must not mute our microphone"
        );
        let muted = render(&mut app, &context, vec![]);
        assert!(texts(&muted).contains(&"You muted Maya"));
        // Escape closes it; your own face opens it with nothing expanded.
        render(
            &mut app,
            &context,
            vec![egui::Event::Key {
                key: egui::Key::Escape,
                physical_key: None,
                pressed: true,
                repeat: false,
                modifiers: egui::Modifiers::NONE,
            }],
        );
        assert!(app.call_list.is_none());
        secondary_click(&mut app, &context, faces[0].center());
        assert_eq!(app.call_list, Some(super::CallList { audio: None }));
        let list = render(&mut app, &context, vec![]);
        assert!(!texts(&list).contains(&"User volume"));
        // Audio opens a row's controls; an outside click closes the list.
        click(
            &mut app,
            &context,
            node_center(&list, "Audio controls for Alex"),
        );
        assert_eq!(
            app.call_list
                .as_ref()
                .and_then(|list| list.audio.as_deref()),
            Some("fixture-alex")
        );
        render(&mut app, &context, vec![]);
        click(&mut app, &context, egui::pos2(1000.0, 500.0));
        assert!(app.call_list.is_none());
        // And Close does too.
        secondary_click(&mut app, &context, faces[2].center());
        let list = render(&mut app, &context, vec![]);
        click(&mut app, &context, node_center(&list, "Close"));
        assert!(app.call_list.is_none());
        app.voice.set_participant_playback(
            "fixture-maya",
            crate::media::TrackPlayback {
                gain_percent: 170,
                muted: false,
            },
        );
        secondary_click(&mut app, &context, faces[1].center());
        let restored = render(&mut app, &context, vec![]);
        assert!(
            !texts(&restored)
                .iter()
                .any(|text| text.starts_with("You muted "))
        );
        assert!(
            app.navigation_target.is_none(),
            "the list never opens the chat"
        );
        render(
            &mut app,
            &context,
            vec![egui::Event::Key {
                key: egui::Key::Escape,
                physical_key: None,
                pressed: true,
                repeat: false,
                modifiers: egui::Modifiers::NONE,
            }],
        );
        // Faces offer the list to screen readers as a context-menu action,
        // and Shift+F10 on the card's focused row opens it too.
        let maya = output
            .platform_output
            .accesskit_update
            .as_ref()
            .unwrap()
            .nodes
            .iter()
            .find(|(_, node)| node.label() == Some("Maya"))
            .unwrap();
        assert!(
            maya.1
                .supports_action(egui::accesskit::Action::ShowContextMenu)
        );
        render(
            &mut app,
            &context,
            vec![egui::Event::AccessKitActionRequest(
                egui::accesskit::ActionRequest {
                    action: egui::accesskit::Action::ShowContextMenu,
                    target: maya.0,
                    data: None,
                },
            )],
        );
        assert_eq!(
            app.call_list,
            Some(super::CallList {
                audio: Some("fixture-maya".into())
            })
        );
        app.call_list = None;
        let output = render(&mut app, &context, vec![]);
        let row = output
            .platform_output
            .accesskit_update
            .as_ref()
            .unwrap()
            .nodes
            .iter()
            .find(|(_, node)| node.label() == Some("general"))
            .map(|(id, _)| *id)
            .unwrap();
        render(
            &mut app,
            &context,
            vec![egui::Event::AccessKitActionRequest(
                egui::accesskit::ActionRequest {
                    action: egui::accesskit::Action::Focus,
                    target: row,
                    data: None,
                },
            )],
        );
        render(
            &mut app,
            &context,
            vec![egui::Event::Key {
                key: egui::Key::F10,
                physical_key: None,
                pressed: true,
                repeat: false,
                modifiers: egui::Modifiers::SHIFT,
            }],
        );
        assert_eq!(app.call_list, Some(super::CallList { audio: None }));
        assert!(app.navigation_target.is_none());
    }

    #[test]
    fn own_face_and_status_use_local_intent_instead_of_stale_snapshot() {
        for (snapshot, muted, deafened) in [
            (true, false, false),
            (false, true, false),
            (false, true, true),
        ] {
            let context = egui::Context::default();
            context.enable_accesskit();
            let mut app = CaperApp::new(
                &context,
                crate::api::Api::new("http://127.0.0.1:9").unwrap(),
                Some("parity-voice-connected"),
            );
            app.call_list = Some(super::CallList::default());
            for participant in &mut app.voice.participants {
                participant.muted = snapshot;
                participant.deafened = snapshot;
            }
            app.voice.state.audio.set_muted(muted);
            app.voice.state.audio.set_deafened(deafened);
            // The list is an area: its first pass only measures it.
            render(&mut app, &context, vec![]);
            let output = render(&mut app, &context, vec![]);
            let labels = output
                .platform_output
                .accesskit_update
                .as_ref()
                .unwrap()
                .nodes
                .iter()
                .filter_map(|(_, node)| node.label().map(str::to_owned))
                .collect::<Vec<_>>();
            let own = match (muted, deafened) {
                (_, true) => "Fixture Owner (you), deafened",
                (true, false) => "Fixture Owner (you), muted",
                _ => "Fixture Owner (you)",
            };
            assert!(labels.contains(&own.to_owned()), "{own}: {labels:?}");
            let maya = if snapshot { "Maya, deafened" } else { "Maya" };
            assert!(labels.contains(&maya.to_owned()), "{maya}: {labels:?}");
            // The account bar and the card show the same intent.
            let mic = if muted {
                "Unmute microphone"
            } else {
                "Mute microphone"
            };
            assert_eq!(labels.iter().filter(|label| *label == mic).count(), 2);
            let shown = texts(&output);
            let status = |text: &str| shown.contains(&text);
            // The list's statuses: yours from your intent, Maya's from hers.
            assert_eq!(
                status("Deafened"),
                deafened || snapshot,
                "{snapshot} {muted} {deafened}: {shown:?}"
            );
            assert_eq!(status("Muted"), muted && !deafened);
        }
    }

    #[test]
    fn call_card_opens_its_chat_anywhere_but_its_controls_without_replacing_call_or_denied_chat() {
        for space in [Some("space0000001"), Some("other-space"), None] {
            let context = egui::Context::default();
            let mut app = CaperApp::new(
                &context,
                crate::api::Api::new("http://127.0.0.1:9").unwrap(),
                Some("parity-voice-connected"),
            );
            let channel = if space.is_some() {
                "chan00000002"
            } else {
                "general"
            };
            app.voice.active_space = space.map(str::to_owned);
            app.voice.state.phase = Phase::Connected(crate::state::CallContext {
                channel_id: channel.into(),
                channel_name: "design".into(),
                space_name: "Voice Space".into(),
            });
            let call = app.voice.state.phase.clone();
            let call_generation = app.voice.state.generation;
            let original_chat = app.selected_channel.clone();
            app.draft = "Unsent text".into();
            render(&mut app, &context, vec![]);
            let output = render(&mut app, &context, vec![]);
            let listed = space == Some("space0000001");
            let card = output
                .shapes
                .iter()
                .find_map(|shape| match &shape.shape {
                    egui::Shape::Rect(rect)
                        if rect.fill == super::LIVE_CARD
                            && rect.stroke.color == super::LIVE_CARD_BORDER =>
                    {
                        Some(rect.rect)
                    }
                    _ => None,
                })
                .expect("the call's card");
            let channels = text_position(&output, "Channels");
            // The card's own controls, not the account bar's.
            let control = |output: &egui::FullOutput, label: &str| {
                output
                    .platform_output
                    .accesskit_update
                    .as_ref()
                    .unwrap()
                    .nodes
                    .iter()
                    .filter(|(_, node)| node.label() == Some(label))
                    .filter_map(|(_, node)| node.bounds())
                    .map(|bounds| {
                        egui::Rect::from_min_max(
                            egui::pos2(bounds.x0 as f32, bounds.y0 as f32),
                            egui::pos2(bounds.x1 as f32, bounds.y1 as f32),
                        )
                    })
                    .find(|bounds| card.contains_rect(*bounds))
                    .unwrap_or_else(|| panic!("the card's {label}"))
            };
            assert!(
                output
                    .platform_output
                    .accesskit_update
                    .as_ref()
                    .unwrap()
                    .nodes
                    .iter()
                    .any(|(_, node)| node.label() == Some("Your call in #design")),
                "the card is named for screen readers"
            );
            if listed {
                // #design's own row heads the card, in its place in the list.
                assert!(node_bounds(&output, "Open #design").is_none());
                let row = node_bounds(&output, "design").unwrap();
                assert!(card.contains_rect(row) && row.top() - card.top() < 16.0);
                assert!(channels.y < card.top());
                assert!(node_bounds(&output, "general").unwrap().bottom() < card.top());
                assert!(card.bottom() < node_bounds(&output, "planning").unwrap().top());
                // The ⋯ menu keeps its own click.
                render(
                    &mut app,
                    &context,
                    vec![egui::Event::PointerMoved(row.center())],
                );
                let hovered = render(&mut app, &context, vec![]);
                click(
                    &mut app,
                    &context,
                    node_center(&hovered, "Channel options for design"),
                );
                assert!(app.navigation_target.is_none(), "the menu opens no chat");
                render(
                    &mut app,
                    &context,
                    vec![egui::Event::Key {
                        key: egui::Key::Escape,
                        physical_key: None,
                        pressed: true,
                        repeat: false,
                        modifiers: egui::Modifiers::NONE,
                    }],
                );
            } else {
                // Another space's call names its space after the channel,
                // and its card sits above the channels.
                let link = node_center(&output, "Open #design in Voice Space");
                assert!(card.contains(link) && link.y - card.top() < 30.0);
                assert!(card.bottom() < channels.y);
            }
            assert_eq!(texts(&output).contains(&"Voice Space"), !listed);
            // Mute, Deafen and Leave keep their own clicks: twice each
            // leaves the call as it was.
            for label in ["Mute microphone", "Deafen audio"] {
                let bounds = control(&output, label);
                click(&mut app, &context, bounds.center());
                click(&mut app, &context, bounds.center());
                assert!(app.navigation_target.is_none(), "{label} opens no chat");
            }
            assert!(!app.voice.state.audio.muted && !app.voice.state.audio.deafened);
            assert!(control(&output, "Leave voice").height() > 0.0);
            // Anywhere else on the card opens the call's chat.
            let open = egui::pos2(card.left() + 5.0, card.center().y);
            click(&mut app, &context, open);
            let target = app
                .navigation_target
                .as_ref()
                .expect("the card must request navigation, not connection details");
            assert_eq!(target.space.as_deref(), space);
            assert_eq!(target.channel.as_deref(), space.map(|_| "chan00000002"));
            assert!(app.dialog.is_none());
            assert_eq!(app.selected_channel, original_chat);
            app.accept_navigation(
                app.generation,
                app.navigation,
                Err(LoadError {
                    message: "Channel denied".into(),
                    access_denied: true,
                    space_access_denied: false,
                }),
            );
            assert_eq!(app.selected_channel, original_chat);
            assert_eq!(app.draft, "Unsent text");
            assert_eq!(app.voice.state.phase, call);
            click(&mut app, &context, open);
            let detail = app.detail.as_ref().unwrap().clone();
            let prepared = || {
                let mut detail = detail.clone();
                if let Some(space) = space {
                    detail.space.id = space.into();
                }
                let mut history = history(channel);
                history.space.id = space.unwrap_or("general").into();
                crate::worker::PreparedNavigation {
                    detail: space.map(|_| detail),
                    conversation: Some((history, Ok(session()))),
                }
            };
            app.accept_navigation(app.generation + 1, app.navigation, Ok(prepared()));
            assert_eq!(
                app.selected_channel, original_chat,
                "another account epoch must not commit"
            );
            app.accept_navigation(app.generation, app.navigation, Ok(prepared()));
            assert_eq!(app.selected_channel.as_deref(), Some(channel));
            assert_eq!(app.voice.state.phase, call);
            assert_eq!(
                app.voice.state.generation, call_generation,
                "opening chat must not rejoin voice"
            );
        }
    }

    #[test]
    fn leave_space_is_nonowner_only_and_clears_private_conversation() {
        let context = egui::Context::default();
        let mut app = CaperApp::new(
            &context,
            crate::api::Api::new("http://127.0.0.1:9").unwrap(),
            Some("parity-desktop"),
        );
        assert!(app.owner());
        assert!(!app.can_leave_space());
        app.account.as_mut().unwrap().id = "fixture-maya".into();
        assert!(!app.owner());
        assert!(app.can_leave_space());
        let space = app.selected_space.clone().unwrap();
        // Exercise leaving the last account space, with no demo fallback.
        app.spaces.retain(|entry| entry.id == space);
        assert!(!app.needs_first_space());
        app.draft = "private draft".into();
        app.pending = Some(PendingSend::prepare(None, "private draft", Vec::new()));
        app.pending_reactions.insert(
            ("message".into(), "👍".into()),
            PendingReaction {
                desired: true,
                sent: true,
                visible: true,
                superseded: false,
            },
        );
        app.reaction_errors
            .insert("message".into(), "failed".into());
        assert!(app.timeline.messages().next().is_some());
        app.select_channel("next".into(), false);
        let stale_generation = app.generation;
        let stale_navigation = app.navigation;
        app.admin_result(crate::worker::AdminResult::SpaceLeft(space.clone()));
        assert!(!app.spaces.iter().any(|entry| entry.id == space));
        assert!(app.detail.is_none());
        assert!(app.selected_space.is_none());
        assert!(app.selected_channel.is_none());
        assert!(app.session.is_none());
        assert!(app.timeline.messages().next().is_none());
        assert!(app.draft.is_empty());
        assert!(app.pending.is_none());
        assert!(app.pending_reactions.is_empty());
        assert!(app.reaction_errors.is_empty());
        app.accept_navigation(
            stale_generation,
            app.navigation,
            Ok(crate::worker::PreparedNavigation {
                detail: None,
                conversation: Some((history("old-private"), Ok(session()))),
            }),
        );
        assert!(
            app.selected_channel.is_none(),
            "late old generation ignored"
        );
        assert!(app.timeline.messages().next().is_none());
        assert!(!app.can_leave_space());
        app.accept_navigation(
            stale_generation,
            stale_navigation,
            Ok(crate::worker::PreparedNavigation {
                detail: None,
                conversation: Some((history("next"), Ok(session()))),
            }),
        );
        assert!(app.selected_channel.is_none());
        assert!(app.timeline.messages().next().is_none());
        // Like web, an account with no spaces is asked to name its first one.
        assert!(app.needs_first_space());
    }

    #[test]
    fn leaving_space_clears_private_state_before_opening_remaining_space() {
        let context = egui::Context::default();
        let mut app = CaperApp::new(
            &context,
            crate::api::Api::new("http://127.0.0.1:9").unwrap(),
            Some("parity-desktop"),
        );
        app.token = Some("fixture-token".into());
        app.spaces.retain(|entry| !entry.demo);
        let mut remaining = app.spaces[0].clone();
        remaining.id = "remaining-space".into();
        app.spaces.push(remaining);
        let space = app.selected_space.clone().unwrap();
        let generation = app.generation;
        app.session = Some(session());
        app.draft = "private draft".into();
        app.admin_result(crate::worker::AdminResult::SpaceLeft(space));

        assert!(app.generation > generation);
        assert!(app.selected_space.is_none());
        assert!(app.selected_channel.is_none());
        assert!(app.session.is_none());
        assert!(app.timeline.messages().next().is_none());
        assert!(app.draft.is_empty());
        assert_eq!(
            app.navigation_target
                .as_ref()
                .and_then(|target| target.space.as_deref()),
            Some("remaining-space")
        );
    }

