    fn open_loaded_thread(app: &mut CaperApp, root: &str) {
        app.thread_view = Some(super::ThreadView {
            root: root.into(),
            loading: false,
            has_more: false,
            before: None,
            error: None,
            window: None,
            has_newer: false,
            retry_older: false,
        });
    }

