        messages[3].created_at = (now - chrono::Duration::seconds(10)).to_rfc3339();
        app.timeline.reset(messages, "4").unwrap();
        app.session = Some(crate::model::ChatSession {
            token: "fixture-token".into(),
            author: mine.clone(),
        });
