    #[test]
    fn call_order_keeps_you_first_then_join_order_whatever_the_roster_order() {
        let person = |id: &str| crate::model::VoiceOccupant {
            id: id.into(),
            avatar_id: None,
            avatar_asset: None,
            avatar_url: None,
            name: id.into(),
            muted: false,
            deafened: false,
        };
        let ids = |people: &[crate::model::VoiceOccupant]| {
            people
                .iter()
                .map(|person| person.id.clone())
                .collect::<Vec<_>>()
        };
        let mut order = Vec::new();
        // The server sorts by participant ID, not by when people joined.
        super::follow_join_order(&mut order, &["d", "me", "z"]);
        let people = vec![person("d"), person("me"), person("z")];
        assert_eq!(
            ids(&super::in_call_order(people, &order, "me")),
            ["me", "d", "z"]
        );
        // A newcomer sorts first on the server but joins the end here.
        super::follow_join_order(&mut order, &["a", "d", "me", "z"]);
        let people = vec![person("a"), person("d"), person("me"), person("z")];
        assert_eq!(
            ids(&super::in_call_order(people, &order, "me")),
            ["me", "d", "z", "a"]
        );
        // Someone leaving closes the gap without reordering the rest.
        super::follow_join_order(&mut order, &["a", "me", "z"]);
        assert_eq!(order, ["me", "z", "a"]);
        let people = vec![person("a"), person("me"), person("z")];
        assert_eq!(
            ids(&super::in_call_order(people, &order, "me")),
            ["me", "z", "a"]
        );
    }

    #[test]
    fn full_list_status_puts_your_mute_then_speaking_then_their_own_state() {
        use super::{MUTED, TERRACOTTA_BRIGHT, VOICE_SESSION_GREEN, participant_status};
        assert_eq!(participant_status("Maya", false, false, false, false), None);
        assert_eq!(
            participant_status("Maya", true, false, false, false),
            Some(("Speaking".into(), VOICE_SESSION_GREEN))
        );
        assert_eq!(
            participant_status("Maya", false, true, false, false),
            Some(("Muted".into(), MUTED))
        );
        assert_eq!(
            participant_status("Maya", false, true, true, false),
            Some(("Deafened".into(), MUTED))
        );
        assert_eq!(
            participant_status("Maya", true, false, false, true),
            Some(("You muted Maya".into(), TERRACOTTA_BRIGHT))
        );
        assert_eq!(
            super::participant_label("Maya", true, false, false),
            "Maya, speaking"
        );
        assert_eq!(
            super::participant_label("Maya", false, true, true),
            "Maya, deafened"
        );
        assert_eq!(
            super::participant_label("Maya", false, true, false),
            "Maya, muted"
        );
        assert_eq!(
            super::participant_label("Maya", false, false, false),
            "Maya"
        );
    }

    /// Like `text_position`, scrolling the open dialog down until `label`'s
    /// click point is inside its clip: Manage space's icon and Invite link
    /// sections can push Members below the fold at the test window size.
    fn scrolled_text_position(
        app: &mut CaperApp,
        context: &egui::Context,
        label: &str,
    ) -> egui::Pos2 {
        for _ in 0..12 {
            let output = render(app, context, vec![]);
            let unclipped = output.shapes.iter().any(|shape| {
                matches!(&shape.shape, egui::Shape::Text(text)
                    if text.galley.job.text == label
                        && shape.clip_rect.contains(text.pos + egui::vec2(4.0, 4.0)))
            });
            if unclipped {
                return text_position(&output, label);
            }
            render(
                app,
                context,
                vec![
                    egui::Event::PointerMoved(egui::pos2(720.0, 450.0)),
                    egui::Event::MouseWheel {
                        unit: egui::MouseWheelUnit::Point,
                        delta: egui::vec2(0.0, -200.0),
                        modifiers: egui::Modifiers::NONE,
                    },
                ],
            );
        }
        panic!("missing {label} after scrolling")
    }

    fn text_position(output: &egui::FullOutput, label: &str) -> egui::Pos2 {
        output
            .shapes
            .iter()
            .find_map(|shape| match &shape.shape {
                egui::Shape::Text(text) if text.galley.job.text == label => {
                    Some(text.pos + egui::vec2(4.0, 4.0))
                }
                _ => None,
            })
            .or_else(|| labelled_center(output, label))
            .unwrap_or_else(|| panic!("missing {label}"))
    }

    fn click_opening(
        app: &mut CaperApp,
        context: &egui::Context,
        pos: egui::Pos2,
    ) -> Option<String> {
        let mut opened = None;
        for pressed in [true, false] {
            let output = render(
                app,
                context,
                vec![
                    egui::Event::PointerMoved(pos),
                    egui::Event::PointerButton {
                        pos,
                        button: egui::PointerButton::Primary,
                        pressed,
                        modifiers: egui::Modifiers::NONE,
                    },
                ],
            );
            opened = opened.or_else(|| opened_url(&output).map(str::to_owned));
        }
        opened
    }

    #[test]
    fn hovering_files_shows_the_drop_overlay_until_they_leave() {
        fn hover(
            app: &mut CaperApp,
            context: &egui::Context,
            hovered_files: Vec<egui::HoveredFile>,
            time: f64,
        ) -> egui::FullOutput {
            context.run(
                egui::RawInput {
                    time: Some(time),
                    screen_rect: Some(egui::Rect::from_min_size(
                        egui::Pos2::ZERO,
                        egui::vec2(1440.0, 900.0),
                    )),
                    hovered_files,
                    ..Default::default()
                },
                |context| app.page(context),
            )
        }
        let has_text = |output: &egui::FullOutput, label: &str| {
            output.shapes.iter().any(|shape| {
                matches!(&shape.shape, egui::Shape::Text(text) if text.galley.job.text == label)
            })
        };
        let context = egui::Context::default();
        let mut app = CaperApp::new(
            &context,
            crate::api::Api::new("http://127.0.0.1:9").unwrap(),
            Some("parity-attachments"),
        );
        assert!(app.can_attach());
        hover(&mut app, &context, vec![], 0.0);
        let (title, detail) =
            crate::file_drop::text(app.channel_name(), false, app.draft_files.len());
        let file = egui::HoveredFile {
            path: Some("TEST FIXTURE photo.png".into()),
            mime: String::new(),
        };
        // It fades in from the moment the drag arrives.
        hover(&mut app, &context, vec![file.clone()], 1.0);
        assert_eq!(app.file_drop_since, Some(1.0));
        let output = hover(&mut app, &context, vec![file.clone()], 2.0);
        assert!(has_text(&output, &title) && has_text(&output, &detail));
        assert_eq!(app.file_drop_since, Some(1.0));
        // The animation keeps the frames coming while the drag stays.
        assert_eq!(
            output.viewport_output[&egui::ViewportId::ROOT].repaint_delay,
            std::time::Duration::ZERO
        );
        let output = hover(&mut app, &context, vec![], 3.0);
        assert!(!has_text(&output, &title));
        assert!(app.file_drop_since.is_none());

        // Nowhere to attach: no overlay.
        app.uploads = None;
        let output = hover(&mut app, &context, vec![file], 4.0);
        assert!(!has_text(&output, &title));
    }

    #[test]
    fn attachments_send_retries_once_and_waits_for_the_complete_selection() {
        for fail_again in [false, true] {
            let (_, mut app) = fixture("parity-attachments");
            app.session = Some(session());
            app.token = Some("fixture-token".into());
            app.draft = "keep the entire selection".into();
            let attachment = app.draft_files[0].attachment.clone().unwrap();
            app.send_message();
            assert!(app.upload_send_intent.is_some());
            assert!(app.pending.is_none());
            assert!(app.draft_files[2].uploading);
            app.upload_update(3, crate::worker::UploadUpdate::Progress(0.4));
            app.send_message();
            assert_eq!(
                app.draft_files[2].progress, 0.4,
                "duplicate Send must not restart uploads"
            );
            let result = if fail_again {
                Err(crate::uploads::UploadError::new("offline again"))
            } else {
                let mut ready = attachment.clone();
                ready.id = "retry-ready".into();
                Ok(ready)
            };
            app.upload_update(3, crate::worker::UploadUpdate::Finished(result));
            assert!(app.pending.is_none(), "never send a successful subset");
            let mut ready = attachment;
            ready.id = "original-ready".into();
            app.upload_update(2, crate::worker::UploadUpdate::Finished(Ok(ready)));
            assert!(app.upload_send_intent.is_none());
            if fail_again {
                assert!(app.pending.is_none());
                assert_eq!(app.draft, "keep the entire selection");
                assert_eq!(app.draft_files.len(), 3);
                assert!(app.draft_files[2].error.is_some());
                app.finish_upload_send_intent();
                assert!(
                    !app.draft_files[2].uploading,
                    "failure never retries itself"
                );
            } else {
                let pending = app.pending.as_ref().unwrap();
                assert_eq!(
                    pending
                        .attachments
                        .iter()
                        .map(|file| file.id.as_str())
                        .collect::<Vec<_>>(),
                    ["fixture-draft", "original-ready", "retry-ready"]
                );
                let id = pending.id.clone();
                app.send_message();
                assert_eq!(app.pending.as_ref().unwrap().id, id);
                assert!(app.draft_files.is_empty());
            }
        }
    }

    #[test]
    fn attachments_send_cancels_stale_composers() {
        for change in 0..10 {
            let (_, mut app) = fixture("parity-attachments");
            app.session = Some(session());
            app.token = Some("fixture-token".into());
            let root = (change >= 8).then(|| "thread".to_owned());
            if let Some(root) = &root {
                for file in &mut app.draft_files {
                    file.thread_root_id = Some(root.clone());
                }
                app.thread_drafts
                    .insert(root.clone(), ("thread text".into(), false));
            }
            app.send_message_to(root, false);
            assert!(app.upload_send_intent.is_some());
            match change {
                0 => app.draft.push_str("edited"),
                1 => {
                    app.remove_draft(1);
                }
                2 => app.selected_channel = Some("different".into()),
                3 => app.generation += 1,
                4 => app.session = None,
                5 => app.close_thread(),
                6 => {
                    let reply =
                        model::MessageReply::from_message(app.timeline.messages().next().unwrap());
                    app.reply_targets.insert("channel".into(), reply);
                }
                7 => {
                    app.draft_files[0].thread_root_id = Some("different-thread".into());
                }
                8 => app.thread_drafts.get_mut("thread").unwrap().1 = true,
                _ => app
                    .thread_drafts
                    .get_mut("thread")
                    .unwrap()
                    .0
                    .push_str("edited"),
            }
            app.finish_upload_send_intent();
            assert!(app.upload_send_intent.is_none());
            assert!(app.pending.is_none());
        }
    }

    #[test]
    fn attachments_render_by_status_and_open_in_the_viewer_or_browser() {
        let context = egui::Context::default();
        context.enable_accesskit();
        let mut app = CaperApp::new(
            &context,
            crate::api::Api::new("http://127.0.0.1:9").unwrap(),
            Some("parity-attachments"),
        );
        app.draft_files[1].local_path = Some(std::env::temp_dir().join("selected diagram #1.png"));
        app.attachment_housekeeping(&context);
        render(&mut app, &context, vec![]);
        let output = render(&mut app, &context, vec![]);
        for label in [
            "TEST FIXTURE report.pdf",
            "TEST FIXTURE archive.zip",
            "File removed",
            "Audio · 1.2 MB",
            "Couldn't process this file",
            "Processing… 45%",
            "Processing…",
            "GIF",
            "Sending 45%",
            "Retry upload",
        ] {
            text_position(&output, label);
        }
        // The file-only message renders no empty text row.
        assert!(!output.shapes.iter().any(|shape| matches!(
            &shape.shape,
            egui::Shape::Text(text) if text.galley.job.text.is_empty() && text.galley.size().y > 0.0
                && text.pos.x > 60.0 && text.pos.x < 80.0
        )));
        let pdf = text_position(&output, "TEST FIXTURE report.pdf");
        assert_eq!(
            click_opening(&mut app, &context, pdf).as_deref(),
            Some("https://fixture.invalid/original/fixture-pdf")
        );
        // Images and videos open the in-app viewer, not the browser: here the
        // message's screenshot and animation, at the animation.
        let gif = text_position(&output, "GIF");
        assert_eq!(click_opening(&mut app, &context, gif), None);
        let viewer = app.viewer.take().expect("the viewer opens");
        assert_eq!((viewer.index(), viewer.len()), (1, 2));
        // Removed, failed and processing files are not links.
        for label in [
            "File removed",
            "Couldn't process this file",
            "Processing… 45%",
            "Processing…",
        ] {
            let position = text_position(&output, label);
            assert_eq!(click_opening(&mut app, &context, position), None, "{label}");
        }
        // An unfinished draft previews its local original without removing it.
        assert!(
            !output.shapes.iter().any(|shape| matches!(
                &shape.shape, egui::Shape::Text(text)
                    if text.galley.job.text == "TEST FIXTURE diagram.png"
                        || text.galley.job.text == "1.6 MB → 143 KB"
                        || text.galley.job.text == "Failed to upload."
            )),
            "draft names, bytes and full errors belong in accessible hover text only"
        );
        let nodes = &output
            .platform_output
            .accesskit_update
            .as_ref()
            .unwrap()
            .nodes;
        let tiles: Vec<_> = output
            .shapes
            .iter()
            .filter_map(|shape| match &shape.shape {
                egui::Shape::Rect(rect)
                    if rect.fill == super::SURFACE
                        && (rect.rect.width() - rect.rect.height()).abs() < 0.1
                        && (80.0..=104.0).contains(&rect.rect.width()) =>
                {
                    Some(rect.rect)
                }
                _ => None,
            })
            .collect();
        assert!(tiles.len() >= 3, "each draft has a compact square surface");
        let retry = node_bounds(
            &output,
            "Retry uploading TEST FIXTURE large.mov: Failed to upload.",
        )
        .expect("accessible retry control");
        assert!(
            tiles.iter().any(|tile| tile.contains_rect(retry)),
            "Retry must fit inside its square tile, even with the app's larger default button height"
        );
        let preview = nodes
            .iter()
            .find(|(_, node)| {
                node.label()
                    .is_some_and(|label| label.starts_with("Preview TEST FIXTURE diagram.png\n"))
            })
            .unwrap()
            .1
            .bounds()
            .unwrap();
        let draft = egui::pos2(
            (preview.x1 - 5.0) as f32,
            ((preview.y0 + preview.y1) / 2.0) as f32,
        );
        let url = click_opening(&mut app, &context, draft).expect("draft preview opens");
        assert!(url.starts_with("file:///"));
        assert!(url.ends_with("/selected%20diagram%20%231.png"));
        assert_eq!(app.draft_files.len(), 3);

        // Empty and multiline drafts share one message-box surface with Attach.
        for draft in ["", "First line\nSecond line\nThird line"] {
            app.draft = draft.into();
            context.enable_accesskit();
            render(&mut app, &context, vec![]);
            let output = render(&mut app, &context, vec![]);
            let bounds = output
                .platform_output
                .accesskit_update
                .as_ref()
                .unwrap()
                .nodes
                .iter()
                .find(|(_, node)| node.label() == Some("Attach files"))
                .unwrap()
                .1
                .bounds()
                .unwrap();
            let attach = egui::Rect::from_min_max(
                egui::pos2(bounds.x0 as f32, bounds.y0 as f32),
                egui::pos2(bounds.x1 as f32, bounds.y1 as f32),
            );
            let emoji = node_bounds(&output, "Insert emoji").expect("emoji control");
            assert!(
                output.shapes.iter().any(|shape| matches!(&shape.shape,
                    egui::Shape::Rect(rect) if rect.fill == super::COMPOSER
                        && rect.rect.shrink(4.0).contains_rect(attach)
                        && rect.rect.shrink(4.0).contains_rect(emoji)
                )),
                "{draft:?}: Attach and Emoji hover targets need space inside the message box"
            );
        }
        context.enable_accesskit();
        let output = render(&mut app, &context, vec![]);
        let bounds = output
            .platform_output
            .accesskit_update
            .as_ref()
            .unwrap()
            .nodes
            .iter()
            .find(|(_, node)| node.label() == Some("Remove TEST FIXTURE diagram.png"))
            .unwrap()
            .1
            .bounds()
            .unwrap();
        let remove = egui::pos2(
            ((bounds.x0 + bounds.x1) / 2.0) as f32,
            ((bounds.y0 + bounds.y1) / 2.0) as f32,
        );
        assert_eq!(
            click_opening(&mut app, &context, remove),
            None,
            "Remove must not open the preview below it"
        );
        assert_eq!(app.draft_files.len(), 2);

        // A failed video still offers removal through its context menu, even
        // without a playable local URL. Opening the menu never previews it.
        let output = render(&mut app, &context, vec![]);
        let corner = node_bounds(&output, "Remove TEST FIXTURE large.mov").unwrap();
        let pos = corner.center() + egui::vec2(-30.0, 25.0);
        for pressed in [true, false] {
            let output = render(
                &mut app,
                &context,
                vec![
                    egui::Event::PointerMoved(pos),
                    egui::Event::PointerButton {
                        pos,
                        button: egui::PointerButton::Secondary,
                        pressed,
                        modifiers: egui::Modifiers::NONE,
                    },
                ],
            );
            assert!(opened_url(&output).is_none());
        }
        render(&mut app, &context, vec![]);
        let output = render(&mut app, &context, vec![]);
        assert_eq!(app.draft_files.len(), 2, "opening is not removal");
        assert_eq!(
            click_opening(
                &mut app,
                &context,
                text_position(&output, "Remove attachment")
            ),
            None
        );
        assert_eq!(app.draft_files.len(), 1);
        assert_eq!(app.draft_files[0].name, "TEST FIXTURE photo.jpg");

        // More than four uploads use the full desktop composer, not a fixed tray.
        while app.draft_files.len() < 10 {
            let (_, more) = fixture("parity-attachments");
            app.draft_files.extend(more.draft_files);
        }
        app.draft_files.truncate(10);
        for (index, draft) in app.draft_files.iter_mut().enumerate() {
            draft.key = index as u64;
            draft.name = format!("TEST FIXTURE wrap {index}.png");
            draft.local_path = Some(std::env::temp_dir().join(&draft.name));
        }
        render(&mut app, &context, vec![]);
        let output = render(&mut app, &context, vec![]);
        let nodes = &output
            .platform_output
            .accesskit_update
            .as_ref()
            .unwrap()
            .nodes;
        let previews: Vec<_> = (0..10)
            .map(|index| {
                nodes
                    .iter()
                    .find(|(_, node)| {
                        node.label().is_some_and(|label| {
                            label.starts_with(&format!("Preview TEST FIXTURE wrap {index}.png\n"))
                        })
                    })
                    .unwrap()
                    .1
                    .bounds()
                    .unwrap()
            })
            .collect();
        let columns = previews
            .iter()
            .take_while(|tile| (tile.y0 - previews[0].y0).abs() < 1.0)
            .count();
        assert!(
            columns > 4 && columns < 10,
            "desktop fills the row, then wraps: {previews:?}"
        );
        assert!(previews[columns].y0 > previews[0].y0);
        let attach = node_bounds(&output, "Attach files").unwrap();
        let composer = output
            .shapes
            .iter()
            .find_map(|shape| match &shape.shape {
                egui::Shape::Rect(rect)
                    if rect.fill == super::COMPOSER && rect.rect.contains_rect(attach) =>
                {
                    Some(rect.rect)
                }
                _ => None,
            })
            .unwrap();
        assert!(
            previews
                .iter()
                .all(|tile| (tile.x1 - tile.x0 - 104.0).abs() < 1.0
                    && (tile.y1 - tile.y0 - 104.0).abs() < 1.0
                    && tile.x0 >= composer.left() as f64
                    && tile.x1 <= composer.right() as f64),
            "every square stays within the composer's horizontal edges"
        );
    }

    #[test]
    fn a_touch_flick_from_an_image_never_opens_it_on_release() {
        let context = egui::Context::default();
        let mut app = CaperApp::new(
            &context,
            crate::api::Api::new("http://127.0.0.1:9").unwrap(),
            Some("parity-attachments"),
        );
        render(&mut app, &context, vec![]);
        let output = render(&mut app, &context, vec![]);
        let gif = text_position(&output, "GIF");
        // What egui-winit sends for one finger: the release keeps the last
        // moved position, and a fast flick's final stretch arrives with it.
        let touch = |phase, pos| egui::Event::Touch {
            device_id: egui::TouchDeviceId(0),
            id: egui::TouchId(1),
            phase,
            pos,
            force: None,
        };
        let flick = |app: &mut CaperApp, lift: egui::Pos2, hook: bool| {
            render(
                app,
                &context,
                vec![
                    touch(egui::TouchPhase::Start, gif),
                    egui::Event::PointerMoved(gif),
                    egui::Event::PointerButton {
                        pos: gif,
                        button: egui::PointerButton::Primary,
                        pressed: true,
                        modifiers: egui::Modifiers::NONE,
                    },
                ],
            );
            let mut events = vec![
                touch(egui::TouchPhase::End, lift),
                egui::Event::PointerButton {
                    pos: gif,
                    button: egui::PointerButton::Primary,
                    pressed: false,
                    modifiers: egui::Modifiers::NONE,
                },
                egui::Event::PointerGone,
            ];
            if hook {
                super::pointer_follows_touch_release(&mut events);
            }
            render(app, &context, events);
            render(app, &context, vec![]);
            app.viewer.take().is_some()
        };
        let away = gif + egui::vec2(-120.0, 0.0);
        assert!(
            flick(&mut app, away, false),
            "egui alone treats it as a tap"
        );
        assert!(!flick(&mut app, away, true), "a flick is not a tap");
        // A still tap still opens it.
        assert!(flick(&mut app, gif, true));
        let mut tap = vec![
            touch(egui::TouchPhase::End, gif),
            egui::Event::PointerButton {
                pos: gif,
                button: egui::PointerButton::Primary,
                pressed: false,
                modifiers: egui::Modifiers::NONE,
            },
        ];
        super::pointer_follows_touch_release(&mut tap);
        assert_eq!(tap.len(), 2, "nothing to add when it lifts where it moved");
    }

    #[test]
    fn attachment_events_update_messages_and_progress() {
        let context = egui::Context::default();
        let mut app = CaperApp::new(
            &context,
            crate::api::Api::new("http://127.0.0.1:9").unwrap(),
            Some("parity-attachments"),
        );
        let channel = app.selected_channel.clone().unwrap();
        let message = app.timeline.messages().nth(2).unwrap().clone();
        app.gateway(GatewayEvent::AttachmentProgress {
            generation: app.generation,
            channel: channel.clone(),
            attachment: "fixture-video".into(),
            percent: 80,
        });
        assert_eq!(app.attachment_progress.get("fixture-video"), Some(&80));
        let mut ready = message.content.attachments.clone();
        ready[1].status = model::AttachmentStatus::Ready;
        ready[1].url = Some("https://fixture.invalid/original/fixture-video".into());
        let update: model::AttachmentUpdate = serde_json::from_value(serde_json::json!({
            "type": "message.attachments", "schemaVersion": 1, "channelId": channel,
            "seq": "5", "messageId": message.id, "attachments": ready
        }))
        .unwrap();
        app.gateway(GatewayEvent::Attachments {
            generation: app.generation,
            channel: channel.clone(),
            update,
        });
        let updated = app
            .timeline
            .messages()
            .find(|item| item.id == message.id)
            .unwrap();
        assert_eq!(
            updated.content.attachments[1].status,
            model::AttachmentStatus::Ready
        );
        assert_eq!(updated.attachments_seq.as_deref(), Some("5"));
        assert_eq!(app.timeline.cursor(), "5");
        assert!(!app.attachment_progress.contains_key("fixture-video"));
        // Events for another channel are ignored.
        app.gateway(GatewayEvent::AttachmentProgress {
            generation: app.generation,
            channel: "elsewhere".into(),
            attachment: "fixture-video".into(),
            percent: 10,
        });
        assert!(!app.attachment_progress.contains_key("fixture-video"));
    }

    #[test]
    fn attachment_readiness_never_moves_the_composer() {
        let context = egui::Context::default();
        context.enable_accesskit();
        let mut app = CaperApp::new(
            &context,
            crate::api::Api::new("http://127.0.0.1:9").unwrap(),
            Some("parity-desktop"),
        );
        app.token = Some("fixture-account".into());
        app.session = Some(session());
        let mut bounds = None;
        for ready in [false, true, false] {
            app.uploads = ready.then(crate::compress::Compression::default);
            render(&mut app, &context, vec![]);
            let output = render(&mut app, &context, vec![]);
            let nodes = &output
                .platform_output
                .accesskit_update
                .as_ref()
                .unwrap()
                .nodes;
            let attach = &nodes
                .iter()
                .find(|(_, node)| node.label() == Some("Attach files"))
                .expect("the attach button stays present")
                .1;
            assert_eq!(attach.is_disabled(), !ready);
            let editor = &nodes
                .iter()
                .find(|(_, node)| node.role() == egui::accesskit::Role::MultilineTextInput)
                .unwrap()
                .1;
            if let Some(previous) = bounds {
                assert_eq!(
                    editor.bounds(),
                    Some(previous),
                    "upload readiness must not move or resize the editor"
                );
            }
            bounds = editor.bounds();
            assert!(bounds.is_some());
        }
    }

    #[test]
    fn attach_needs_uploads_and_a_writable_channel_and_drafts_gate_sending() {
        let context = egui::Context::default();
        let mut app = CaperApp::new(
            &context,
            crate::api::Api::new("http://127.0.0.1:9").unwrap(),
            Some("parity-attachments"),
        );
        assert!(app.can_attach());
        app.uploads = None;
        assert!(!app.can_attach(), "usage failure disables Attach");
        app.uploads = Some(crate::compress::Compression::default());
        let channel = app.selected_channel.clone().unwrap();
        app.detail
            .as_mut()
            .unwrap()
            .channels
            .iter_mut()
            .find(|entry| entry.id == channel)
            .unwrap()
            .joined = false;
        assert!(!app.can_attach(), "read-only previews cannot attach");
        app.detail
            .as_mut()
            .unwrap()
            .channels
            .iter_mut()
            .find(|entry| entry.id == channel)
            .unwrap()
            .joined = true;

        // Unfinished or failed files block sending; nothing is sent.
        app.send_message();
        assert!(app.error.is_none(), "the file chip owns progress and Retry");
        assert!(app.pending.is_none());
        app.remove_draft(3);
        app.send_message();
        assert!(app.error.is_none());
        app.remove_draft(2);
        assert!(app.draft.is_empty());
        // A file-only message sends with empty text and its attachment ids.
        app.send_message();
        let pending = app.pending.clone().unwrap();
        assert_eq!(pending.text, "");
        assert_eq!(
            pending
                .attachments
                .iter()
                .map(|attachment| attachment.id.as_str())
                .collect::<Vec<_>>(),
            ["fixture-draft"]
        );
        assert!(
            app.draft_files.is_empty(),
            "the pending row owns sent files"
        );
        // A retry resends the same id and files.
        app.pending.as_mut().unwrap().sending = false;
        app.send_message();
        assert_eq!(app.pending.as_ref().unwrap().id, pending.id);
        assert_eq!(
            app.pending.as_ref().unwrap().attachments,
            pending.attachments
        );
        let output = render(&mut app, &context, vec![]);
        text_position(&output, "Processing…");
    }

    #[test]
    fn upload_updates_fill_drafts_and_abandoned_uploads_are_cancelled() {
        let context = egui::Context::default();
        let mut app = CaperApp::new(
            &context,
            crate::api::Api::new("http://127.0.0.1:9").unwrap(),
            Some("parity-attachments"),
        );
        app.upload_update(2, crate::worker::UploadUpdate::Progress(0.75));
        app.upload_update(2, crate::worker::UploadUpdate::Progress(0.5));
        assert_eq!(
            app.draft_files[1].progress, 0.75,
            "progress never goes back"
        );
        let attachment = model::Attachment {
            id: "uploaded".into(),
            kind: model::AttachmentKind::Image,
            content_type: "image/png".into(),
            name: "diagram.png".into(),
            size: 52_000,
            width: Some(320),
            height: Some(180),
            duration_ms: None,
            preview: false,
            url: None,
            preview_url: None,
            unavailable: false,
            status: model::AttachmentStatus::Processing,
            animated: false,
        };
        app.upload_update(
            2,
            crate::worker::UploadUpdate::Finished(Ok(attachment.clone())),
        );
        assert_eq!(app.draft_files[1].attachment, Some(attachment));
        assert!(
            app.local_media.iter().any(|(id, _)| id == "uploaded"),
            "own images show without a download"
        );
        // A local copy decoded after the upload finished still reaches the
        // sent message.
        app.upload_update(
            1,
            crate::worker::UploadUpdate::Prepared {
                name: "photo.jpg".into(),
                kind: model::AttachmentKind::Image,
                source_size: 1_677_722,
                stored_size: 146_432,
            },
        );
        assert_eq!(app.draft_files[0].source_size, 1_677_722);
        assert_eq!(app.draft_files[0].stored_size, Some(146_432));
        app.upload_update(
            1,
            crate::worker::UploadUpdate::Thumbnail(egui::ColorImage::filled(
                [2, 2],
                egui::Color32::WHITE,
            )),
        );
        assert!(app.local_media.iter().any(|(id, _)| id == "fixture-draft"));
        // Late updates for removed drafts are ignored.
        app.remove_draft(2);
        app.upload_update(2, crate::worker::UploadUpdate::Progress(1.0));
        let cancels: Vec<_> = app
            .draft_files
            .iter()
            .map(|draft| draft.cancel.clone())
            .collect();
        let channel = app.draft_files[0].channel.clone();
        app.selected_channel = Some("another-channel".into());
        app.attachment_housekeeping(&context);
        assert!(app.draft_files.is_empty());
        assert!(
            cancels
                .iter()
                .all(|cancel| !cancel.load(std::sync::atomic::Ordering::Relaxed)),
            "files of another conversation are kept, not cancelled"
        );
        assert_eq!(app.staged_files[&channel].len(), cancels.len());
    }

    #[test]
    fn switching_conversations_keeps_each_ones_text_files_and_thread_replies() {
        let context = egui::Context::default();
        let mut app = CaperApp::new(
            &context,
            crate::api::Api::new("http://127.0.0.1:9").unwrap(),
            Some("parity-attachments"),
        );
        let first = app.selected_channel.clone().unwrap();
        let keys: Vec<_> = app.draft_files.iter().map(|draft| draft.key).collect();
        let cancels: Vec<_> = app
            .draft_files
            .iter()
            .map(|draft| draft.cancel.clone())
            .collect();
        assert!(!keys.is_empty());
        app.draft = "Unsent in the first conversation".into();
        app.thread_drafts
            .insert("root-message".into(), ("Unsent reply".into(), true));
        app.reload_selected_channel("chan00000002".into(), false);
        assert!(app.draft.is_empty() && app.draft_files.is_empty());
        // A stashed upload still reports progress while its conversation is closed.
        app.upload_update(keys[0], crate::worker::UploadUpdate::Progress(0.9));
        app.draft = "Unsent in the second conversation".into();
        app.reload_selected_channel(first.clone(), false);
        assert_eq!(app.draft, "Unsent in the first conversation");
        assert_eq!(
            app.draft_files
                .iter()
                .map(|draft| draft.key)
                .collect::<Vec<_>>(),
            keys
        );
        assert!(app.draft_files[0].progress >= 0.9);
        assert!(
            cancels
                .iter()
                .all(|cancel| !cancel.load(std::sync::atomic::Ordering::Relaxed)),
            "switching never cancels an upload"
        );
        assert_eq!(
            app.drafts["chan00000002"],
            "Unsent in the second conversation"
        );
        assert_eq!(app.thread_drafts["root-message"].0, "Unsent reply");
    }

    #[test]
    fn attachment_only_thread_reply_owns_its_files_through_retry_renewal_and_edit() {
        let context = egui::Context::default();
        let mut app = CaperApp::new(
            &context,
            crate::api::Api::new("http://127.0.0.1:9").unwrap(),
            Some("parity-thread-attachments-ready"),
        );
        let root = app.thread_view.as_ref().unwrap().root.clone();
        let attachment = app.draft_files[0].attachment.clone().unwrap();
        let thread_key = app.draft_files[0].key;
        // Neither another thread's failed upload nor the channel's files/text
        // can block or be consumed by this attachment-only reply.
        app.restore_drafts(vec![attachment.clone()], None);
        app.restore_drafts(vec![attachment.clone()], Some("other-root".into()));
        app.draft_files.last_mut().unwrap().attachment = None;
        app.draft_files.last_mut().unwrap().error = Some("Failed to upload.".into());
        app.draft = "Keep the channel draft".into();
        app.thread_drafts
            .insert("other-root".into(), ("Keep the other reply".into(), true));
        app.thread_drafts.entry(root.clone()).or_default().1 = true;
        render(&mut app, &context, vec![]);
        let output = render(&mut app, &context, vec![]);
        click(&mut app, &context, text_position(&output, "Send reply"));
        let first = app.pending.clone().expect("attachment-only replies send");
        assert_eq!(first.text, "");
        assert_eq!(first.attachments, vec![attachment]);
        assert_eq!(first.thread_root_id.as_deref(), Some(root.as_str()));
        assert!(first.broadcast);
        assert_eq!(app.pending_files.len(), 1);
        assert_eq!(app.pending_files[0].key, thread_key);
        assert_eq!(app.draft_file_count(None), 1);
        assert_eq!(app.draft_file_count(Some("other-root")), 1);
        assert_eq!(app.thread_drafts[&root], ("".into(), false));

        app.sent(Err(crate::worker::SendFailure {
            status: None,
            message: "offline".into(),
            code: None,
        }));
        app.send_message_to(Some(root.clone()), false);
        assert_eq!(app.pending.as_ref().unwrap().id, first.id);
        assert_eq!(app.pending.as_ref().unwrap().attachments, first.attachments);
        assert!(
            app.pending.as_ref().unwrap().broadcast,
            "retries keep the original destination choices"
        );

        app.sent(Err(crate::worker::SendFailure {
            status: Some(409),
            message: "expired".into(),
            code: Some("attachment_unavailable".into()),
        }));
        app.upload_update(
            thread_key,
            crate::worker::UploadUpdate::Finished(Err(crate::uploads::UploadError::new(
                "storage offline",
            ))),
        );
        app.close_thread();
        render(&mut app, &context, vec![]);
        let output = render(&mut app, &context, vec![]);
        click(&mut app, &context, text_position(&output, "Review reply"));
        assert_eq!(app.thread_view.as_ref().unwrap().root, root);
        render(&mut app, &context, vec![]);
        let output = render(&mut app, &context, vec![]);
        click(&mut app, &context, text_position(&output, "Retry"));
        let mut renewed = first.attachments[0].clone();
        renewed.id = "renewed-thread-upload".into();
        app.upload_update(
            thread_key,
            crate::worker::UploadUpdate::Finished(Ok(renewed.clone())),
        );
        let pending = app.pending.as_ref().unwrap();
        assert_ne!(
            pending.id, first.id,
            "definitive expiry starts a new command after renewal"
        );
        assert_eq!(pending.attachments, vec![renewed.clone()]);
        assert_eq!(pending.thread_root_id, first.thread_root_id);
        assert!(pending.broadcast && pending.sending && !pending.upload_failed);

        app.sent(Err(crate::worker::SendFailure {
            status: Some(422),
            message: "Rejected fixture".into(),
            code: None,
        }));
        app.thread_drafts.entry(root.clone()).or_default().0 = "New unsent reply".into();
        render(&mut app, &context, vec![]);
        let output = render(&mut app, &context, vec![]);
        click(&mut app, &context, text_position(&output, "Edit"));
        assert!(
            app.pending.is_some(),
            "Edit never overwrites new thread text"
        );
        app.thread_drafts.entry(root.clone()).or_default().0.clear();
        render(&mut app, &context, vec![]);
        let output = render(&mut app, &context, vec![]);
        click(&mut app, &context, text_position(&output, "Edit"));
        assert!(app.pending.is_none());
        assert_eq!(app.thread_drafts[&root], ("".into(), true));
        assert_eq!(app.draft_file_count(Some(&root)), 1);
        let restored = app
            .draft_files
            .iter()
            .find(|file| file.key == thread_key)
            .unwrap();
        assert_eq!(restored.attachment, Some(renewed));
        assert_eq!(restored.thread_root_id.as_deref(), Some(root.as_str()));
        assert_eq!(app.draft, "Keep the channel draft");
        assert_eq!(
            app.thread_drafts["other-root"],
            ("Keep the other reply".into(), true)
        );
        assert_eq!(app.draft_file_count(None), 1);
        assert_eq!(app.draft_file_count(Some("other-root")), 1);
    }

    #[test]
    fn thread_picker_and_uploads_keep_the_original_destination_after_navigation() {
        let context = egui::Context::default();
        let mut app = CaperApp::new(
            &context,
            crate::api::Api::new("http://127.0.0.1:9").unwrap(),
            Some("parity-thread-attachments-ready"),
        );
        let channel = app.selected_channel.clone().unwrap();
        let root = app.thread_view.as_ref().unwrap().root.clone();
        let attachment = app.draft_files[0].attachment.clone().unwrap();
        app.draft_files[0].upload_expired = true;
        let (sender, receiver) = std::sync::mpsc::channel();
        app.file_picker = Some(super::FilePicker {
            channel: channel.clone(),
            thread_root_id: Some(root.clone()),
            receiver,
        });
        app.close_thread();
        app.reload_selected_channel("chan00000002".into(), false);
        app.draft = "Keep the second channel".into();
        sender
            .send(vec!["picked-for-original-thread.txt".into()])
            .unwrap();
        app.attachment_housekeeping(&context);
        assert!(app.draft_files.is_empty());
        let files = &app.staged_files[&channel];
        assert_eq!(files.len(), 2);
        assert!(
            files
                .iter()
                .all(|file| file.thread_root_id.as_deref() == Some(&root))
        );
        let picked_key = files[1].key;
        app.upload_update(
            picked_key,
            crate::worker::UploadUpdate::Finished(Ok(attachment)),
        );
        app.reload_selected_channel(channel.clone(), false);
        app.open_thread(root.clone());
        assert_eq!(app.draft_file_count(None), 0);
        assert_eq!(app.draft_file_count(Some(&root)), 2);
        assert!(
            app.draft_files[0].uploading && app.draft_files[0].attachment.is_none(),
            "expired files renew on return"
        );
        assert!(
            app.draft_files[1].attachment.is_some(),
            "closed destinations still receive upload results"
        );
        app.close_thread();
        app.open_thread(root.clone());
        assert_eq!(app.draft_file_count(Some(&root)), 2);
        assert_eq!(app.drafts["chan00000002"], "Keep the second channel");

        // A picker completed in the same channel still belongs to the original
        // thread, even when another thread is now open.
        let (sender, receiver) = std::sync::mpsc::channel();
        app.file_picker = Some(super::FilePicker {
            channel,
            thread_root_id: Some(root.clone()),
            receiver,
        });
        app.open_thread("other-root".into());
        sender
            .send(vec!["another-original-thread.txt".into()])
            .unwrap();
        app.attachment_housekeeping(&context);
        assert_eq!(app.draft_file_count(Some(&root)), 3);
        assert_eq!(app.draft_file_count(Some("other-root")), 0);
        assert_eq!(app.draft_file_count(None), 0);
        let (sender, receiver) = std::sync::mpsc::channel();
        app.file_picker = Some(super::FilePicker {
            channel: app.selected_channel.clone().unwrap(),
            thread_root_id: Some(root),
            receiver,
        });
        let cancels: Vec<_> = app
            .draft_files
            .iter()
            .map(|file| file.cancel.clone())
            .collect();
        app.logout();
        assert!(app.file_picker.is_none());
        assert!(sender.send(vec!["after-signout.txt".into()]).is_err());
        assert!(app.draft_files.is_empty() && app.staged_files.is_empty());
        assert!(
            cancels
                .iter()
                .all(|cancel| cancel.load(std::sync::atomic::Ordering::Relaxed))
        );
    }

    #[test]
    fn thread_and_channel_attachment_limits_and_drop_destinations_are_independent() {
        let context = egui::Context::default();
        let mut app = CaperApp::new(
            &context,
            crate::api::Api::new("http://127.0.0.1:9").unwrap(),
            Some("parity-thread-attachments-ready"),
        );
        let root = app.thread_view.as_ref().unwrap().root.clone();
        let attachment = app.draft_files[0].attachment.clone().unwrap();
        app.restore_drafts(
            vec![attachment.clone(); crate::uploads::MAX_ATTACHMENTS],
            None,
        );
        app.restore_drafts(
            vec![attachment; crate::uploads::MAX_ATTACHMENTS],
            Some("other-root".into()),
        );
        render(&mut app, &context, vec![]);
        for pos in [
            app.thread_drop_rect.unwrap().center(),
            egui::pos2(700.0, 300.0),
        ] {
            let _ = context.run(
                egui::RawInput {
                    screen_rect: Some(egui::Rect::from_min_size(
                        egui::Pos2::ZERO,
                        egui::vec2(1440.0, 900.0),
                    )),
                    events: vec![egui::Event::PointerMoved(pos)],
                    dropped_files: vec![egui::DroppedFile {
                        path: Some("dropped.txt".into()),
                        ..Default::default()
                    }],
                    ..Default::default()
                },
                |context| {
                    app.attachment_housekeeping(context);
                    app.page(context);
                },
            );
        }
        assert_eq!(
            app.draft_file_count(Some(&root)),
            2,
            "a full channel or other thread cannot block a thread drop"
        );
        assert_eq!(app.draft_file_count(None), crate::uploads::MAX_ATTACHMENTS);
        assert_eq!(
            app.draft_file_count(Some("other-root")),
            crate::uploads::MAX_ATTACHMENTS
        );
        let output = render(&mut app, &context, vec![]);
        let nodes = &output
            .platform_output
            .accesskit_update
            .as_ref()
            .unwrap()
            .nodes;
        assert!(
            nodes
                .iter()
                .any(|(_, node)| node.label() == Some("Attach files") && !node.is_disabled()),
            "thread Attach stays enabled independently of the channel limit"
        );
        app.add_files(
            vec!["extra.txt".into(); crate::uploads::MAX_ATTACHMENTS],
            Some(root.clone()),
        );
        assert_eq!(
            app.draft_file_count(Some(&root)),
            crate::uploads::MAX_ATTACHMENTS
        );
        assert_eq!(
            app.error.as_deref(),
            Some("Only 8 more files can be attached.")
        );
    }

    #[test]
    fn rejected_message_requires_explicit_edit_or_dismiss_and_protects_new_draft() {
        let context = egui::Context::default();
        let mut app = CaperApp::new(
            &context,
            crate::api::Api::new("http://127.0.0.1:9").unwrap(),
            Some("parity-desktop"),
        );
        app.session = Some(session());
        app.draft = "rejected original".into();
        app.send_message();
        assert!(app.draft.is_empty());
        let original_id = app.pending.as_ref().unwrap().id.clone();
        app.sent(Err(crate::worker::SendFailure {
            status: Some(422),
            message: "Rejected fixture".into(),
            code: None,
        }));
        app.draft = "next unsent draft".into();
        app.send_message();
        assert_eq!(app.pending.as_ref().unwrap().id, original_id);
        assert!(
            !app.pending.as_ref().unwrap().sending,
            "rejected IDs cannot be retried"
        );
        render(&mut app, &context, vec![]);
        let output = render(&mut app, &context, vec![]);
        click(&mut app, &context, text_position(&output, "Edit"));
        assert_eq!(
            app.draft, "next unsent draft",
            "Edit must not overwrite new text"
        );
        assert!(app.pending.is_some());
        click(&mut app, &context, text_position(&output, "Dismiss"));
        assert!(app.pending.is_none());
        assert_eq!(app.draft, "next unsent draft");

        app.draft = "rejected original".into();
        app.send_message();
        let second_id = app.pending.as_ref().unwrap().id.clone();
        app.sent(Err(crate::worker::SendFailure {
            status: Some(400),
            message: "Rejected again".into(),
            code: None,
        }));
        render(&mut app, &context, vec![]);
        let output = render(&mut app, &context, vec![]);
        click(&mut app, &context, text_position(&output, "Edit"));
        assert_eq!(app.draft, "rejected original");
        assert!(app.pending.is_none());
        assert!(context.memory(|memory| memory.has_focus(egui::Id::new("message-composer"))));
        app.send_message();
        assert_ne!(app.pending.as_ref().unwrap().id, second_id);
    }

    #[test]
    fn unavailable_send_renews_silently_and_failed_upload_retries_without_losing_drafts() {
        let context = egui::Context::default();
        let mut app = CaperApp::new(
            &context,
            crate::api::Api::new("http://127.0.0.1:9").unwrap(),
            Some("parity-attachments"),
        );
        app.session = Some(session());
        app.draft_files.retain(|draft| draft.attachment.is_some());
        app.draft = "keep this text".into();
        app.send_message();
        let first = app.pending.clone().unwrap();
        app.pending_files[0].upload_expired = true;
        app.sent(Err(crate::worker::SendFailure {
            status: None,
            message: "offline".into(),
            code: None,
        }));
        app.draft = "keep this text".into(); // A new draft with the same text.
        app.send_message();
        assert_eq!(
            app.pending.as_ref().unwrap().id,
            first.id,
            "unknown outcomes never replace the command"
        );
        assert_eq!(app.pending.as_ref().unwrap().attachments, first.attachments);
        app.sent(Err(crate::worker::SendFailure {
            status: Some(409),
            message: "must stay invisible".into(),
            code: Some("attachment_unavailable".into()),
        }));
        assert!(app.pending.as_ref().unwrap().sending);
        assert!(app.pending.as_ref().unwrap().rejection.is_none());
        assert!(app.error.is_none());
        let key = app.pending_files[0].key;
        app.upload_update(
            key,
            crate::worker::UploadUpdate::Finished(Err(crate::uploads::UploadError::new(
                "storage offline",
            ))),
        );
        render(&mut app, &context, vec![]);
        let output = render(&mut app, &context, vec![]);
        text_position(&output, "Failed to upload.");
        click(&mut app, &context, text_position(&output, "Retry"));
        let mut renewed = first.attachments[0].clone();
        renewed.id = "fresh-upload".into();
        app.upload_update(
            key,
            crate::worker::UploadUpdate::Finished(Ok(renewed.clone())),
        );
        let pending = app.pending.as_ref().unwrap();
        assert_ne!(pending.id, first.id);
        assert_eq!(pending.attachments, vec![renewed]);
        assert_eq!(pending.text, "keep this text");
        assert!(pending.sending);
        assert!(!pending.upload_failed);
        assert_eq!(app.draft, "keep this text");
        assert!(app.draft_files.is_empty());
    }

    #[test]
    fn both_confirmation_paths_preserve_the_next_draft() {
        for via_gateway in [false, true] {
            let context = egui::Context::default();
            let mut app = CaperApp::new(
                &context,
                crate::api::Api::new("http://127.0.0.1:9").unwrap(),
                Some("parity-desktop"),
            );
            app.session = Some(session());
            app.draft = "sent original".into();
            app.send_message();
            assert!(app.draft.is_empty());
            app.draft = "different new draft".into();
            let mut message = app.timeline.messages().last().unwrap().clone();
            message.seq = (message.seq.parse::<u64>().unwrap() + 1).to_string();
            message.id = "confirmation".into();
            message.client_message_id = app.pending.as_ref().unwrap().id.clone();
            message.content.text = "sent original".into();
            message.author = app.session.as_ref().unwrap().author.clone();
            if via_gateway {
                app.gateway(crate::gateway::GatewayEvent::Message {
                    generation: app.generation,
                    channel: message.channel_id.clone(),
                    message: Box::new(message),
                });
            } else {
                app.sent(Ok(message));
            }
            assert!(app.pending.is_none());
            assert_eq!(app.draft, "different new draft");
        }
    }

