    #[test]
    fn login_field_keeps_focus_through_a_request_and_edits_clear_its_error() {
        for verifying in [false, true] {
            let context = egui::Context::default();
            let mut app = CaperApp::new(
                &context,
                crate::api::Api::new("http://127.0.0.1:9").unwrap(),
                Some("signed-out"),
            );
            app.email = "fixture@example.test".into();
            app.challenge = verifying.then(|| "fixture-challenge".into());
            let field = egui::Id::new(if verifying {
                "sign-in-code"
            } else {
                "sign-in-email"
            });
            let focused =
                |context: &egui::Context| context.memory(|memory| memory.has_focus(field));
            render(&mut app, &context, vec![]);
            assert!(focused(&context), "focused when the page opens");
            app.loading = true;
            render(&mut app, &context, vec![]);
            assert!(focused(&context), "read-only, not disabled, while pending");
            // Enter gives up focus; the finished request returns it.
            context.memory_mut(|memory| memory.surrender_focus(field));
            render(&mut app, &context, vec![]);
            app.loading = false;
            app.error = Some("That code is incorrect or expired.".into());
            render(&mut app, &context, vec![]);
            assert!(focused(&context), "refocused when the request ends");
            render(&mut app, &context, vec![egui::Event::Text("A".into())]);
            assert!(app.error.is_none(), "editing clears the error");
            if verifying {
                app.code.clear();
                render(
                    &mut app,
                    &context,
                    vec![egui::Event::Paste(" abc-234".into())],
                );
                assert_eq!(app.code, "ABC234", "cleaned before the six-character limit");
            }
        }
    }

    #[test]
    fn login_spacing_does_not_add_automatic_gaps_to_explicit_spacers() {
        for (width, verifying) in [
            (1440.0, false),
            (1440.0, true),
            (390.0, false),
            (390.0, true),
        ] {
            let context = egui::Context::default();
            let mut app = CaperApp::new(
                &context,
                crate::api::Api::new("http://127.0.0.1:9").unwrap(),
                Some("signed-out"),
            );
            app.email = "fixture@example.test".into();
            if verifying {
                app.challenge = Some("fixture-challenge".into());
                app.code = "ABC234".into();
            }
            let mut frame = || {
                context.run(
                    egui::RawInput {
                        screen_rect: Some(egui::Rect::from_min_size(
                            egui::Pos2::ZERO,
                            egui::vec2(width, 844.0),
                        )),
                        ..Default::default()
                    },
                    |context| app.page(context),
                )
            };
            frame();
            // The field takes focus when the page opens, as on web. Measure its
            // resting frame, without egui's 1px focus expansion.
            context.memory_mut(|memory| {
                memory.surrender_focus(egui::Id::new(if verifying {
                    "sign-in-code"
                } else {
                    "sign-in-email"
                }))
            });
            let output = frame();
            let text_rect = |label: &str| {
                output
                    .shapes
                    .iter()
                    .find_map(|shape| match &shape.shape {
                        egui::Shape::Text(text) if text.galley.job.text == label => {
                            Some(egui::Rect::from_min_size(text.pos, text.galley.size()))
                        }
                        _ => None,
                    })
                    .unwrap_or_else(|| panic!("missing {label}"))
            };
            let heading = text_rect(if verifying {
                "Check your email."
            } else {
                "Welcome to Caper"
            });
            let description = text_rect(if verifying {
                "Enter the six-character code sent to fixture@example.test. It expires in 10 minutes."
            } else {
                "Use your email to create an account or return to one. We’ll send a code to your email."
            });
            assert_eq!(description.top() - heading.bottom(), 4.0);
            let control_rect = |height: f32| {
                output
                    .shapes
                    .iter()
                    .find_map(|shape| match &shape.shape {
                        egui::Shape::Rect(rect)
                            if rect.rect.width() > 80.0 && rect.rect.height() == height =>
                        {
                            Some(rect.rect)
                        }
                        _ => None,
                    })
                    .unwrap_or_else(|| panic!("missing {height}px control"))
            };
            assert_eq!(control_rect(58.0).top() - control_rect(52.0).bottom(), 12.0);
            if !verifying {
                assert_eq!(control_rect(58.0).right(), control_rect(52.0).right());
                assert!(control_rect(58.0).width() < control_rect(52.0).width());
            }
            for rect in [heading, description, control_rect(52.0), control_rect(58.0)] {
                assert!(
                    rect.left() >= 8.0 && rect.right() <= width - 8.0,
                    "clipped: {rect:?}"
                );
            }
        }
    }

