    #[test]
    fn launch_stays_on_loading_until_the_first_conversation_opens() {
        let shows = |output: &egui::FullOutput, label: &str| {
            output.shapes.iter().any(|shape| {
                matches!(&shape.shape, egui::Shape::Text(text) if text.galley.job.text == label)
            })
        };
        let context = eframe::egui::Context::default();
        let api = crate::api::Api::new("http://127.0.0.1:9").unwrap();
        let mut app = CaperApp::new(&context, api, Some("signed-out"));
        app.restoring = Some(Instant::now());
        app.establish(
            "account-token".into(),
            account(true),
            Spaces {
                spaces: vec![Space {
                    icon_asset: None,
                    icon_url: None,
                    id: "first-account-space".into(),
                    name: "First".into(),
                    owner_id: "account".into(),
                    inviter: None,
                    demo: false,
                }],
                invitations: Vec::new(),
                limits: None,
            },
        );
        assert!(app.opening);
        render(&mut app, &context, vec![]);
        let output = render(&mut app, &context, vec![]);
        text_position(&output, "Loading your spaces…");
        for hidden in [
            "Welcome to Caper",
            "No joined channels",
            "Browse spaces",
            "Channels",
        ] {
            assert!(!shows(&output, hidden), "{hidden} flashed during launch");
        }

        // The first navigation, whatever its outcome, ends the loading page.
        let (generation, navigation) = (app.generation, app.navigation);
        app.accept_navigation(
            generation,
            navigation,
            Err(LoadError {
                message: "Offline".into(),
                access_denied: false,
                space_access_denied: false,
            }),
        );
        assert!(app.restoring.is_none());
        render(&mut app, &context, vec![]);
        assert!(!shows(
            &render(&mut app, &context, vec![]),
            "Loading your spaces…"
        ));

        // A navigation that never answers cannot hold the loading page past its cap.
        app.restoring = Some(Instant::now() - RESTORE_LIMIT);
        render(&mut app, &context, vec![]);
        assert!(app.restoring.is_none());

        // An account without spaces goes straight to its first-space page.
        app.restoring = Some(Instant::now());
        app.establish("account-token".into(), account(true), spaces());
        assert!(app.restoring.is_none());
    }

    #[test]
    fn older_failure_keeps_conversation_and_send_error_and_retries_separately() {
        let context = egui::Context::default();
        let mut app = CaperApp::new(
            &context,
            crate::api::Api::new("http://127.0.0.1:9").unwrap(),
            Some("parity-desktop"),
        );
        let channel = app.selected_channel.clone().unwrap();
        let count = app.timeline.messages().count();
        app.has_more = true;
        app.error = Some("Send failed".into());
        app.draft = "Keep my draft".into();
        app.accept_older(
            &channel,
            Err(LoadError {
                message: "History unavailable".into(),
                access_denied: false,
                space_access_denied: false,
            }),
        );
        assert_eq!(app.older_error.as_deref(), Some("History unavailable"));
        assert_eq!(app.error.as_deref(), Some("Send failed"));
        assert_eq!(app.timeline.messages().count(), count);
        assert_eq!(app.draft, "Keep my draft");
        app.load_older();
        assert!(app.loading_older);
        assert!(app.older_error.is_none());
        app.older_error = Some("Sentinel".into());
        app.load_older();
        assert_eq!(
            app.older_error.as_deref(),
            Some("Sentinel"),
            "duplicate request must be ignored"
        );
        app.reload_selected_channel("other".into(), false);
        assert!(!app.loading_older);
        assert!(app.older_error.is_none());
        assert!(!app.has_more);
    }

    #[test]
    fn switching_conversations_keeps_each_unsent_draft_until_sign_out() {
        let context = egui::Context::default();
        let mut app = CaperApp::new(
            &context,
            crate::api::Api::new("http://127.0.0.1:9").unwrap(),
            Some("parity-desktop"),
        );
        let first = app.selected_channel.clone().unwrap();
        app.draft = "first draft".into();
        app.reload_selected_channel("other".into(), false);
        assert!(app.draft.is_empty(), "drafts belong to one conversation");
        app.draft = "other draft".into();
        app.reload_selected_channel(first.clone(), false);
        assert_eq!(app.draft, "first draft");
        app.draft.clear();
        app.reload_selected_channel("other".into(), false);
        assert_eq!(app.draft, "other draft");
        app.reload_selected_channel(first.clone(), false);
        assert!(app.draft.is_empty(), "a cleared draft stays cleared");
        app.reload_channel();
        app.draft = "reloaded draft".into();
        app.reload_channel();
        assert_eq!(app.draft, "reloaded draft");
        app.logout();
        assert!(app.draft.is_empty() && app.drafts.is_empty());
    }

